const LAUNCH_CONTEXT_KEY = 'nexus_launch_context';

if (window.location.search.includes('mode=quick')) {
    document.documentElement.classList.add('quick-panel-mode');

    // Chrome caps action popups in screen pixels. At browser zoom > 100%,
    // their CSS viewport is smaller than the intrinsic 796 x 600 bootstrap.
    // Measure that viewport instead of letting the document overflow it.
    let quickLayoutFrame = 0;
    const fitQuickPanel = () => {
        cancelAnimationFrame(quickLayoutFrame);
        quickLayoutFrame = requestAnimationFrame(() => {
            const root = document.documentElement;
            if (!root.classList.contains('quick-panel-window-mode')) {
                const width = Math.min(796, window.innerWidth);
                const height = Math.min(600, window.innerHeight);
                if (width > 0 && height > 0) {
                    root.style.setProperty('width', `${width}px`, 'important');
                    root.style.setProperty('height', `${height}px`, 'important');
                    root.style.setProperty('min-width', '0', 'important');
                    root.style.setProperty('min-height', '0', 'important');
                }
            }
            const panel = document.getElementById('tab-main');
            const grid = document.getElementById('video-grid');
            if (!panel || !grid || panel.clientHeight <= 0) return;
            const style = getComputedStyle(grid);
            const inset = parseFloat(style.paddingTop) + parseFloat(style.paddingBottom);
            const gap = parseFloat(style.rowGap) || 0;
            const rowHeight = Math.max(1, (panel.clientHeight - inset - gap) / 2);
            grid.style.setProperty('grid-auto-rows', `${rowHeight}px`, 'important');
        });
    };
    document.addEventListener('DOMContentLoaded', () => {
        fitQuickPanel();
        const panel = document.getElementById('tab-main');
        if (panel) new ResizeObserver(fitQuickPanel).observe(panel);
    }, { once: true });
    window.addEventListener('resize', fitQuickPanel);
}

