async function initLaunchContext() {
    const params = new URLSearchParams(window.location.search);
    const sourceTabId = Number(params.get('sourceTabId') || 0) || null;
    const sourceWindowId = Number(params.get('sourceWindowId') || 0) || null;
    const hasExplicitLaunchContext = !!(sourceTabId || sourceWindowId);
    let stored = {};
    try {
        stored = await chrome.storage.local.get([LAUNCH_CONTEXT_KEY]);
    } catch { }
    const saved = stored[LAUNCH_CONTEXT_KEY] || {};

    sourceTabContext = {
        sourceTabId: sourceTabId || saved.sourceTabId || null,
        sourceWindowId: sourceWindowId || saved.sourceWindowId || null,
        sourceUrl: hasExplicitLaunchContext ? '' : (saved.sourceUrl || ''),
        sourceTitle: hasExplicitLaunchContext ? '' : (saved.sourceTitle || ''),
        updatedAt: hasExplicitLaunchContext ? Date.now() : (saved.updatedAt || Date.now()),
    };
    window.sourceTabContext = sourceTabContext;

    const tab = await getSourceTab();
    if (tab) {
        sourceTabContext = {
            ...sourceTabContext,
            sourceTabId: tab.id,
            sourceWindowId: tab.windowId,
            sourceUrl: tab.url || sourceTabContext.sourceUrl || '',
            sourceTitle: tab.title || sourceTabContext.sourceTitle || '',
            updatedAt: Date.now(),
        };
        window.sourceTabContext = sourceTabContext;
        try {
            await chrome.storage.local.set({ [LAUNCH_CONTEXT_KEY]: sourceTabContext });
        } catch (error) {
            console.warn('[Nexus Gallery] Launch context storage skipped:', error?.message || error);
        }
    }
}

async function getSourceTab() {
    const isQuickPanel = document.documentElement.classList.contains('quick-panel-mode');

    // In Quick Panel, we always want the currently active tab where the popup was opened.
    if (isQuickPanel) {
        try {
            const [tab] = await chrome.tabs.query({ active: true, lastFocusedWindow: true });
            if (tab?.id && !tab.url?.startsWith(chrome.runtime.getURL(''))) return tab;
        } catch { }
        try {
            const [tab] = await chrome.tabs.query({ active: true, currentWindow: true });
            if (tab?.id && !tab.url?.startsWith(chrome.runtime.getURL(''))) return tab;
        } catch { }
    }

    if (sourceTabContext?.sourceTabId && !isQuickPanel) {
        try {
            const tab = await chrome.tabs.get(sourceTabContext.sourceTabId);
            if (tab?.id && !tab.url?.startsWith(chrome.runtime.getURL(''))) {
                return tab;
            }
        } catch { }
    }

    try {
        const [tab] = await chrome.tabs.query({ active: true, lastFocusedWindow: true });
        if (tab?.id && !tab.url?.startsWith(chrome.runtime.getURL(''))) return tab;
    } catch { }

    try {
        const [tab] = await chrome.tabs.query({ active: true, currentWindow: true });
        if (tab?.id && !tab.url?.startsWith(chrome.runtime.getURL(''))) return tab;
    } catch { }

    return null;
}

