function formatElapsedMs(ms) {
    const safe = Math.max(0, Number(ms || 0) || 0);
    const totalSec = Math.floor(safe / 1000);
    const m = Math.floor(totalSec / 60);
    const s = totalSec % 60;
    return `${String(m).padStart(2, '0')}:${String(s).padStart(2, '0')}`;
}

