                        const img = card?.querySelector('img');
                        const title = a.getAttribute('title') || a.textContent?.trim() || 'Porntrex Video';
                        const rawThumb = img?.getAttribute('data-src') || img?.getAttribute('data-original') || img?.getAttribute('src') || '';
                        let thumbnail = '';
                        try { thumbnail = rawThumb ? new URL(rawThumb, baseUrl).href : ''; } catch { thumbnail = rawThumb; }
