async function resolveVkMetadataBatch(videos) {
    if (!videos || videos.length === 0) return {};
    const urlMap = {};
    const urls = [];
    for (const v of videos) {
        const u = String(v.source_url || v.url || '').trim();
        if (u) { urlMap[u] = v; urls.push(u); }
    }
    if (urls.length === 0) return {};

    // Send up to 10 at once to keep latency reasonable
    const results = {};
    const CHUNK = 40;
    for (let i = 0; i < urls.length; i += CHUNK) {
        const chunk = urls.slice(i, i + CHUNK);
        try {
            const resp = await fetch(`${DASHBOARD_URL}/api/v1/meta/vk`, {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ urls: chunk }),
            });
            if (!resp.ok) { console.warn('[VK meta] endpoint error', resp.status); continue; }
            const data = await resp.json();
            for (const item of (data.results || [])) {
                if (item && item.url) results[item.url] = item;
            }
        } catch (e) {
            console.warn('[VK meta] fetch failed', e);
        }
    }
    return results;
}


