    // Auto-detect turbo.cr videos embedded on current forum/page
    (async () => {
        try {
            const tab = await getSourceTab();
            if (!tab?.id) return;
            const tabUrl = String(tab.url || '');
            // Skip turbo.cr and extension pages themselves
            if (/turbo\.cr/i.test(tabUrl) || tabUrl.startsWith(chrome.runtime.getURL(''))) return;

            // First: scan the tab's DOM for turbo.cr iframes and links
            const [{ result: foundUrls }] = await chrome.scripting.executeScript({
                target: { tabId: tab.id },
                func: () => {
                    const TURBO_RE = /(?:https?:)?\/\/turbo\.cr\/(?:embed|v|d)\/[A-Za-z0-9_-]+/gi;
                    const seen = new Set();
                    const results = [];
                    const addUrl = (raw, title) => {
                        try {
                            const full = String(raw || '').startsWith('//') ? `https:${raw}` : String(raw || '');
                            const url = new URL(full, location.href);
                            const match = url.pathname.match(/\/(?:embed|v|d)\/([^/?#]+)/i);
                            if (!/turbo\.cr$/i.test(url.hostname) || !match) return;
                            const canonical = `${url.protocol}//${url.host}/v/${match[1]}`;
                            if (seen.has(canonical)) return;
                            seen.add(canonical);
                            results.push({ url: canonical, title: title || 'Turbo video' });
                        } catch { }
                    };
                    document.querySelectorAll("iframe[src*='turbo.cr/'], iframe[data-src*='turbo.cr/']").forEach(el => {
                        const post = el.closest('article, .message, .message-inner, [data-content], .post, .entry');
                        const title = post?.querySelector('h1,h2,h3,.title,.message-attribution')?.textContent?.trim() || document.title;
                        addUrl(el.src || el.dataset.src, title);
                    });
                    document.querySelectorAll("a[href*='turbo.cr/v/'], a[href*='turbo.cr/embed/'], a[href*='turbo.cr/d/']").forEach(el => {
                        addUrl(el.href, el.textContent?.trim() || document.title);
                    });
                    const html = document.documentElement?.innerHTML || '';
                    (html.match(TURBO_RE) || []).forEach(url => addUrl(url, document.title));
                    return results;
                }
            }).catch(() => [{ result: [] }]);

            if (!Array.isArray(foundUrls) || !foundUrls.length) return;

            // For each found URL: check background cache first, then resolve
            const resolved = await Promise.all(foundUrls.map(({ url, title }) =>
                new Promise(resolve => {
                    chrome.runtime.sendMessage({ action: 'GET_TURBO_FOR_TAB', tabId: tab.id }, (res) => {
                        const cached = (res?.videos || []).find(v => v.pageUrl === url);
                        if (cached?.streamUrl) {
                            resolve({ url: cached.pageUrl, streamUrl: cached.streamUrl, title: cached.title || title, thumbnail: cached.thumbnail || '', duration: cached.duration || 0 });
                        } else {
                            chrome.runtime.sendMessage({ action: 'NEXUS_TURBO_RESOLVE', url }, (r) => {
                                if (r?.ok && r.streamUrl) resolve({ url, streamUrl: r.streamUrl, title: r.title || title, thumbnail: r.thumbnail || '', duration: r.duration || 0 });
                                else resolve(null);
                            });
                        }
                    });
                })
            ));

            const validVideos = resolved.filter(Boolean);
            if (!validVideos.length) return;

            const idGen = (u) => 'turbo_' + String(u || '').split('/').pop();
            const newEntries = validVideos.map(v => ({
                id: idGen(v.url),
                url: v.url,
                title: v.title || 'Turbo video',
                stream_url: v.streamUrl,
                thumbnail_path: v.thumbnail || '',
                duration: v.duration || 0,
                source_url: tabUrl,
                type: 'video',
                _turboEmbed: true,
            }));

            const existingIds = new Set((allVideos || []).map(v => v.id));
            const toAdd = newEntries.filter(v => !existingIds.has(v.id));
            if (!toAdd.length) return;

            allVideos = [...(allVideos || []), ...toAdd];
            currentlyFilteredVideos = [...allVideos];
            if (typeof applyFilters === 'function') applyFilters();
            if (typeof updateStats === 'function') updateStats();
            if (typeof renderGrid === 'function') renderGrid(currentlyFilteredVideos);

            const folderEl = document.getElementById('folder-name');
            if (folderEl && !folderEl.innerText) folderEl.innerText = 'Turbo embeds';
            showToast(`🎬 Nájdené ${toAdd.length} turbo.cr videá na stránke`, 3000);
        } catch (e) {
            console.warn('[Nexus] Turbo embed scan failed:', e);
        }
    })();

