    // ── SEND TO JDOWNLOADER ──
    // ── JDOWNLOADER EXPORT ──
    // Jedno video = jeden záznam s čistým direct URL (bez #filename= fragmentu –
    // JD m3u8 crawler ho nepozná) + názov súboru, komentár a cieľový priečinok.
    // Používajú sa len polia, ktoré JD Folder Watch naozaj číta.
    async function collectJDownloaderReady() {
        const selectedList = currentlyFilteredVideos.filter(v => selectedVideos.has(v.id));
        const faphouse = selectedList.filter(isFaphouseVideo);
        if (faphouse.length) {
            const tab = await getSourceTab();
            showToast(`Overujem ${faphouse.length} FapHouse zdrojov…`, 3000);
            const errors = [];
            for (let i = 0; i < faphouse.length; i += 3) {
                await Promise.all(faphouse.slice(i, i + 3).map(async video => {
                    try { await resolveFaphouseVideo(video, tab?.id); }
                    catch (error) { errors.push(error.message); }
                }));
            }
            renderGrid(currentlyFilteredVideos);
            updateStats();
            if (errors.length) showToast(`${errors.length} preskočených: ${errors[0]}`, 6000);
        }
        return selectedList.filter(v => !!getCopyableDirectUrl(v));
    }

    function jdCleanTitle(v) {
        return String(v.title || v.originalTitle || 'Video').replace(/[\\/:*?"<>|]+/g, '_').replace(/\s+/g, ' ').trim();
    }

    function jdFileName(v) {
        const q = v.quality ? ` [${v.quality}]` : '';
        return `${jdCleanTitle(v)}${q}.mp4`;
    }

    function jdPageTitle() {
        return (document.getElementById('folder-name')?.innerText || document.title || 'Nexus_Export')
            .replace(/[\\/:*?"<>|]+/g, '_').replace(/\s+/g, ' ').trim();
    }

    function buildJDownloaderCrawljobs(ready, pageTitle) {
        return ready.map(v => {
            const q = v.quality ? ` [${v.quality}]` : '';
            const sizeBytes = getVideoSizeBytes(v);
            const size = sizeBytes ? ` | ${v.sizeEstimated ? 'Odhad streamu' : 'Veľkosť'}: ${formatSizeCompact(sizeBytes)}` : '';
            const dur = Number(v.duration || 0) > 0
                ? ` | Trvanie: ${Math.floor(v.duration / 60)}:${String(Math.round(v.duration % 60)).padStart(2, '0')}`
                : '';
            return {
                text: getCopyableDirectUrl(v),
                packageName: pageTitle,
                filename: jdFileName(v),
                comment: `Názov: ${jdCleanTitle(v)}${q}${size}${dur} | Zdroj: ${v.source_url || v.url || ''}`,
                downloadFolder: pageTitle,
                autoConfirm: true,
                autoStart: false,
                overwritePackagizerEnabled: true
            };
        });
    }

    function downloadJDownloaderCrawljob(ready, pageTitle) {
        const jobs = buildJDownloaderCrawljobs(ready, pageTitle);
        const dateTag = new Date().toISOString().slice(0, 10);
        const crawlFileName = `${pageTitle}_${ready.length}v_${dateTag}.crawljob`;
        const blob = new Blob([JSON.stringify(jobs, null, 2)], { type: 'application/json' });
        const downloadUrl = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = downloadUrl;
        a.download = crawlFileName;
        document.body.appendChild(a);
        a.click();
        setTimeout(() => {
            a.remove();
            URL.revokeObjectURL(downloadUrl);
        }, 1500);
        return crawlFileName;
    }

    // Lokálne FlashGot API JDownloadera (port 9666). `fnames` nesie názvy súborov,
    // `descriptions` komentár – JD ich pri m3u8 rešpektuje (overené v Zachytávači).
    async function sendToJDownloaderApi(ready, pageTitle) {
        const params = new URLSearchParams();
        params.append('urls', ready.map(v => getCopyableDirectUrl(v)).join('\n'));
        const fnames = ready.map(v => jdFileName(v)).join('\n');
        params.append('fnames', fnames);
        params.append('filenames', fnames);
        params.append('descriptions', ready.map(v => {
            const sizeBytes = getVideoSizeBytes(v);
            const size = sizeBytes ? ` | ${formatSizeCompact(sizeBytes)}` : '';
            return `${jdCleanTitle(v)}${v.quality ? ` [${v.quality}]` : ''}${size} | Zdroj: ${v.source_url || v.url || ''}`;
        }).join('\n'));
        params.append('package', pageTitle);
        params.append('source', ready[0]?.source_url || ready[0]?.url || location.href);

        const controller = new AbortController();
        const timer = setTimeout(() => controller.abort(), 4000);
        try {
            const res = await fetch('http://127.0.0.1:9666/flashgot', {
                method: 'POST',
                body: params,
                headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
                signal: controller.signal
            });
            return !!(res && res.ok);
        } catch (_) {
            return false;
        } finally {
            clearTimeout(timer);
        }
    }

    // Send to JDownloader: NAJPRV API (odkazy sú v JD okamžite, s názvami). Súbor sa
    // sťahuje LEN keď JD nereaguje – inak by ten istý zoznam prišiel dvakrát, JD by
    // duplikáty zahodil a na crawljob zahlásil "Invalid container".
    document.getElementById('send-jdownloader-btn')?.addEventListener('click', async () => {
        const ready = await collectJDownloaderReady();
        if (ready.length === 0) {
            showToast('Žiadne priame streamy k dispozícii – najprv Fetch meta / Direct', 2500);
            return;
        }
        const pageTitle = jdPageTitle();
        showToast(`⏳ JDownloader: posielam ${ready.length} videí…`, 1500);
        const apiOk = await sendToJDownloaderApi(ready, pageTitle);
        if (apiOk) {
            showToast(`✅ JDownloader: ${ready.length} videí je v Zachytávači odkazov (balíček „${pageTitle}")`, 3500);
            return;
        }
        const crawlFileName = downloadJDownloaderCrawljob(ready, pageTitle);
        showToast(`⚠ JDownloader nereaguje – stiahnutý ${crawlFileName}. Hoď ho do priečinka folderwatch.`, 5000);
    });

