                        if (/\/(?:search|categories|channels|models|pornstars|tags|latest-updates|most-recent|most-viewed|top-rated|longest|upcoming|page)(?:\/|$)/i.test(p)) return false;
                        if (/^\/members\/\d+(?:\/videos)?$/i.test(p)) return false;
                        if (/^\/(?:albums?|users?)$/i.test(p)) return false;
