async function resolvePornOneMetadata(detailUrl) {
    try {
        const response = await fetch(detailUrl, { credentials: 'include' });
        if (!response.ok) return {};
        const html = await response.text();
        const doc = new DOMParser().parseFromString(html, 'text/html');

        const parseQualityHeight = (value) => {
            const match = String(value || '').match(/(2160|1440|1080|720|480|360)\s*p?/i);
            return match ? (parseInt(match[1], 10) || 0) : 0;
        };
        const qualityFromHeight = (height) => {
            if (height >= 2160) return '4K';
            if (height >= 1440) return '1440p';
            if (height >= 1080) return '1080p';
            if (height >= 720) return '720p';
            if (height >= 480) return '480p';
            if (height >= 360) return '360p';
            return '';
        };
        const parseResolutionDims = (value) => {
            const match = String(value || '').match(/(?:^|[^\d])(\d{3,4})x(\d{3,4})(?:[^\d]|$)/i);
            if (!match) return { width: 0, height: 0, label: '' };
            const width = parseInt(match[1], 10) || 0;
            const height = parseInt(match[2], 10) || 0;
            return { width, height, label: width > 0 && height > 0 ? `${width}x${height}` : '' };
        };

        let bestSource = null;
        Array.from(doc.querySelectorAll('source[src]')).forEach((source) => {
            const src = source.getAttribute('src');
            if (!src) return;
            const abs = new URL(src, detailUrl).href;
            const resAttr = source.getAttribute('res') || source.getAttribute('label') || '';
            const qualityHeight = parseQualityHeight(resAttr);
            const dims = parseResolutionDims(abs);
            const score = qualityHeight || dims.height || 0;
            const candidate = {
                src: abs,
                quality: qualityFromHeight(qualityHeight),
                resolution: dims.label,
                score,
            };
            if (!bestSource || candidate.score > bestSource.score) bestSource = candidate;
        });

        const ldContentUrlMatch = html.match(/"contentUrl"\s*:\s*"([^"]+)"/i);
        const fallbackUrl = (ldContentUrlMatch ? ldContentUrlMatch[1] : null) || '';
        const absFallback = fallbackUrl ? new URL(fallbackUrl, detailUrl).href : '';

        return {
            playbackUrl: bestSource?.src || absFallback || '',
            quality: bestSource?.quality || '',
            resolution: bestSource?.resolution || '',
        };
    } catch {
        return {};
    }
}

async function resolveWhoresHubMetadata(detailUrl) {
    try {
        let targetUrl = detailUrl;
        if (!detailUrl.includes('/embed/')) {
            const videoIdM = detailUrl.match(/\/video(?:s)?\/(\d+)(?:\/|$)/i);
            if (videoIdM) targetUrl = `https://www.whoreshub.com/embed/${videoIdM[1]}/`;
        }

        const resp = await new Promise((resolve) => {
            chrome.runtime.sendMessage({
                action: "FETCH_EMBED_CORS",
                url: targetUrl,
                referer: "https://www.whoreshub.com/",
            }, resolve);
        });

        if (resp && resp.ok && resp.html) {
            const direct = extractMediaUrlFromHtml(resp.html, targetUrl);
            if (direct) return { playbackUrl: direct };
        }
    } catch { }
    return {};
}

async function fetchWhoresHubFileSize(detailUrl) {
    // Fetch the video detail page and extract the highest-quality file size from the Download section.
    // Returns size in bytes, or 0 if unavailable.
    try {
        const videoPageUrl = /\/video(?:s)?\/\d+(?:\/|$)/i.test(detailUrl) ? detailUrl : '';
        if (!videoPageUrl) return 0;
        const resp = await new Promise((resolve) => {
            chrome.runtime.sendMessage({
                action: "FETCH_EMBED_CORS",
                url: videoPageUrl,
                referer: "https://www.whoreshub.com/",
            }, resolve);
        });
        if (!resp?.ok || !resp?.html) return 0;
        // Parse download buttons: "MP4 2160p 4k, 3.49 Gb" / "MP4 1080p, 947.37 Mb"
        const doc = new DOMParser().parseFromString(resp.html, 'text/html');
        const qualityOrder = ['2160', '4k', '1080', '720', '480', '360'];
        let bestSize = 0, bestScore = -1;
        doc.querySelectorAll('.tags-list .btn, .download-link, a.btn').forEach(a => {
            const txt = (a.textContent || '').trim();
            const sizeM = txt.match(/([0-9]+(?:\.[0-9]+)?)\s*(Mb|Gb|MB|GB)/i);
            if (!sizeM) return;
            const num = parseFloat(sizeM[1]);
            const unit = sizeM[2].toLowerCase();
            const bytes = unit.startsWith('g') ? Math.round(num * 1024 * 1024 * 1024) : Math.round(num * 1024 * 1024);
            const txtL = txt.toLowerCase();
            const score = qualityOrder.findIndex(q => txtL.includes(q));
            const normalizedScore = score === -1 ? qualityOrder.length : score;
            if (bestScore === -1 || normalizedScore < bestScore) {
                bestScore = normalizedScore;
                bestSize = bytes;
            }
        });
        return bestSize;
    } catch { return 0; }
}

async function resolveVideoUrl(video, onStatus = null) {
    const url = video.source_url || video.url;
    if (!url) return null;
    if (isFilesterVideo(video)) {
        return await resolveFilesterVideo(video, onStatus);
    }
    if (isFaphouseVideo(video)) {
        // Signed FapHouse URLs have a short lifetime. When Gallery already has
        // a verified, unexpired URL, play it directly instead of depending on
        // the source-tab bridge again (which may not yet be injected after a
        // browser/extension reload).
        const cachedStream = getCopyableDirectUrl(video);
        if (cachedStream) return cachedStream;
        const tab = await getSourceTab();
        await resolveFaphouseVideo(video, tab?.id);
        return getCopyableDirectUrl(video) || null;
    }

    const turboIdFromUrl = String(url).match(/turbo\.cr\/(?:v|d|embed)\/([^/?#]+)/i)?.[1] || '';
    const turboCanonicalUrl = turboIdFromUrl ? `https://turbo.cr/v/${turboIdFromUrl}` : '';

    const existingDirect = String(video.directUrl || '').trim();
    const isCamwhoresPage = /camwhores\.tv\/videos\/\d+/i.test(url);
    const hasCamwhoresDirect = /camwhores\.tv\/get_file\//i.test(existingDirect);
    const isBadBunkrDirect = isBunkrIntermediaryUrl(existingDirect);
    if (
        existingDirect &&
        !isBadBunkrDirect &&
        !(isCamwhoresPage && hasCamwhoresDirect) &&
        !isSuspiciousDirectUrl(existingDirect, getVideoSizeBytes(video))
    ) {
        return existingDirect;
    }

    // If it already looks like a media file, return it
    if (looksLikeDirectMediaUrl(url)) return url;

    console.log(`[Player] Resolving URL for: ${video.title}`);

    // 1. Check background captured streams
    try {
        const captured = await new Promise(resolve => {
            const timeout = setTimeout(() => resolve(null), 1000);
            chrome.runtime.sendMessage({
                action: "GET_CAPTURED_STREAM",
                pageUrl: url,
                duration: Number(video.duration || 0) || 0,
            }, (resp) => {
                clearTimeout(timeout);
                const data = resp?.data || resp || {};
                const ok = resp?.ok === true;
                const rejected = Boolean(data?.rejected);
                const playable = Boolean(data?.playable);
                if (!ok || rejected || !playable) {
                    resolve(null);
                    return;
                }
                const streamUrl = String(data?.streamUrl || '').trim();
                if (streamUrl) {
                    const sizeBytes = Number(data?.sizeBytes || 0) || 0;
                    if ((!video.size || Number(video.size) <= 0) && isUsableVideoSize(sizeBytes, video, streamUrl)) video.size = sizeBytes;
                    if (!video.quality || String(video.quality).toLowerCase() === 'hd' || String(video.quality) === '?') {
                        const inferred = qualityLabelFromHeight(inferVariantHeight(streamUrl));
                        if (inferred) video.quality = inferred;
                    }
                }
                resolve(streamUrl || null);
            });
        });
        if (captured) {
            video.directUrl = captured;
            return captured;
        }
    } catch (e) { }

    // 2. Site-specific quick resolution
    try {
        if (/noodlemagazine\.com/i.test(url)) {
            const meta = await resolveNoodleMetadata(url);
            if (meta?.directUrl) {
                video.directUrl = meta.directUrl;
                return meta.directUrl;
            }
        } else if (/turbo\.cr\/(?:v|d|embed)\//i.test(url)) {
            // Ask background to resolve via signed embed stream extraction
            const turboResolved = await new Promise((resolve) => {
                const timeout = setTimeout(() => resolve(null), 15000);
                chrome.runtime.sendMessage({ action: "NEXUS_TURBO_RESOLVE", url: turboCanonicalUrl || url }, (resp) => {
                    clearTimeout(timeout);
                    resolve(resp?.streamUrl || null);
                });
            });
            if (turboResolved) {
                video.directUrl = turboResolved;
                return turboResolved;
            }
        } else if (/camwhores\.tv/i.test(url)) {
            const meta = await resolveCamwhoresMetadata(url, { force: true });
            if (meta?.playbackUrl) {
                applyCamwhoresMetadataToVideo(video, meta);
                video.directUrl = meta.playbackUrl;
                return meta.playbackUrl;
            }
        } else if (/fullporner\.com/i.test(url)) {
            const direct = await resolveFullpornerDirectUrl(url);
            if (direct) {
                video.directUrl = direct;
                return direct;
            }
        } else if (/pornone\.com/i.test(url)) {
            const meta = await resolvePornOneMetadata(url);
            if (meta.playbackUrl) {
                video.directUrl = meta.playbackUrl;
                return meta.playbackUrl;
            }
        } else if (/whoreshub\.com/i.test(url)) {
            const meta = await resolveWhoresHubMetadata(url);
            if (meta.playbackUrl) {
                video.directUrl = meta.playbackUrl;
                return meta.playbackUrl;
            }
        } else if (/streamtape\.[a-z]+/i.test(url)) {
            const direct = await resolveStreamtapeDirect(url);
            if (direct) {
                video.directUrl = direct;
                return direct;
            }
        } else if (/bunkr/i.test(url)) {
            let direct = await bunkrResolveViaVs(video.bunkr_page_url || url);
            if (direct) {
                video.directUrl = direct;
                return direct;
            }
            if (video.dataId) {
                direct = await bunkrApiResolve(video.dataId);
                if (direct) {
                    video.directUrl = direct;
                    return direct;
                }
            }
            if (video.bunkr_page_url) {
                direct = await bunkrFetchPageExtract(video.bunkr_page_url);
                if (direct) {
                    video.directUrl = direct;
                    return direct;
                }
            }
        } else if (/hornysimp|nsfw247|pornhat|beeg/i.test(url)) {
            // HornySimp, NSFW247, PornHat, Beeg often use embed iframes
            const direct = await resolveHornySimpLikeDirectUrl(video);
            if (direct) {
                video.directUrl = direct;
                return direct;
            }
        }

        // 3. Generic fetch and extract
        const resp = await fetch(url);
        if (resp.ok) {
            const html = await resp.text();
            const direct = extractMediaUrlFromHtml(html, url);
            if (direct) {
                video.directUrl = direct;
                return direct;
            }
        }
    } catch (e) {
        console.warn(`[Player] Resolution failed for ${video.title}`, e);
    }

    return looksLikeDirectMediaUrl(video.url) ? video.url : null;
}

function inferVariantHeight(value) {
    const text = String(value || '').toLowerCase();
    let decoded = text;
    try { decoded = decodeURIComponent(text); } catch { }
    if (/\b8k\b/.test(decoded)) return 4320;
    if (/\b4k\b/.test(decoded)) return 2160;
    if (/\b2k\b/.test(decoded)) return 1440;
    const query = decoded.match(/[?&](?:quality|q|res|resolution|height)=([^&]+)/i);
    if (query) {
        if (/^(?:2k|1440p?)$/i.test(query[1])) return 1440;
        const queryHeight = query[1].match(/^(2160|1080|720|480|360|240)p?$/i);
        if (queryHeight) return parseInt(queryHeight[1], 10) || 0;
    }
    const match = decoded.match(/(?:^|[\/_\-.])(2160|1440|1080|720|480|360|240)(?:p)?(?:[\/_\-.]|$)/i);
    return match ? parseInt(match[1], 10) || 0 : 0;
}

function qualityLabelFromHeight(height) {
    const h = Number(height || 0);
    if (h >= 2160) return '4K';
    if (h >= 1440) return '2K';
    if (h >= 1080) return '1080p';
    if (h >= 720) return '720p';
    if (h >= 480) return '480p';
    if (h >= 360) return '360p';
    if (h >= 240) return '240p';
    return '';
}

function normalizeStreamVariant(raw, fallback = {}) {
    const url = String(raw?.url || raw?.src || '').trim();
    if (!url) return null;
    const width = Number(raw?.width || fallback.width || 0) || 0;
    const explicitHeight = Number(raw?.height || fallback.height || 0) || 0;
    const inferredHeight = inferVariantHeight(raw?.label || raw?.quality || raw?.resolution || url);
    const height = explicitHeight || inferredHeight || 0;
    const quality = String(raw?.quality || fallback.quality || qualityLabelFromHeight(height) || '').trim();
    const resolution = String(raw?.resolution || fallback.resolution || (width > 0 && height > 0 ? `${width}x${height}` : '')).trim();
    const bitrate = Number(raw?.bitrate || raw?.bandwidth || fallback.bitrate || 0) || 0;
    const sizeBytes = Number(raw?.sizeBytes || raw?.size || raw?.size_bytes || 0) || 0;
    const isMaster = Boolean(raw?.master);
    return { url, width, height, quality, resolution, bitrate, sizeBytes, isMaster };
}

function isBogusStreamSize(sizeBytes, variant = {}, video = {}) {
    const size = Number(sizeBytes || 0) || 0;
    if (!size) return false;
    const blob = `${variant?.url || ''} ${video?.url || ''} ${video?.source_url || ''}`.toLowerCase();
    if (!/xvideos\.(?:com|red)|xvideos-cdn\.com/i.test(blob)) return false;
    return size < (1024 * 1024);
}

function isUsableVideoSize(sizeBytes, video = {}, urlHint = '') {
    const size = Number(sizeBytes || 0) || 0;
    if (size <= 0) return false;
    return !isBogusStreamSize(size, { url: urlHint }, video);
}

function getVariantRank(variant = {}, video = {}) {
    const height = Number(variant.height || inferVariantHeight(variant.quality || variant.resolution || variant.url)) || 0;
    const width = Number(variant.width || 0) || 0;
    const bitrate = Number(variant.bitrate || 0) || 0;
    const rawSize = Number(variant.sizeBytes || 0) || 0;
    const size = isBogusStreamSize(rawSize, variant, video) ? 0 : rawSize;
    const hlsBonus = /\.m3u8(?:[?#]|$)/i.test(String(variant.url || '')) ? 500000 : 0;
    return (height * 1000000000) + (width * 100000) + bitrate + Math.min(size, 100000000000) + hlsBonus;
}

async function fetchHlsMasterVariants(playlistUrl, refererUrl) {
    const url = String(playlistUrl || '').trim();
    if (!url || !url.includes('.m3u8')) return [];
    try {
        const headers = refererUrl ? { Referer: refererUrl } : undefined;
        const response = await fetch(url, { credentials: 'include', headers });
        if (!response.ok) return [];
        const text = await response.text();
        if (!text.includes('#EXT-X-STREAM-INF')) return [];

        const lines = text.split(/\r?\n/).map((line) => line.trim()).filter(Boolean);
        const variants = [];
        for (let i = 0; i < lines.length; i += 1) {
            const line = lines[i];
            if (!line.startsWith('#EXT-X-STREAM-INF')) continue;
            const next = lines[i + 1] || '';
            if (!next || next.startsWith('#')) continue;

            const resMatch = line.match(/RESOLUTION=(\d+)x(\d+)/i);
            const bwMatch = line.match(/(?:AVERAGE-)?BANDWIDTH=(\d+)/i);
            const nameMatch = line.match(/NAME="([^"]+)"/i);
            const width = resMatch ? parseInt(resMatch[1], 10) || 0 : 0;
            const height = resMatch ? parseInt(resMatch[2], 10) || 0 : inferVariantHeight(next);
            const bitrate = bwMatch ? parseInt(bwMatch[1], 10) || 0 : 0;
            const quality = nameMatch?.[1] ? String(nameMatch[1]).trim() : qualityLabelFromHeight(height);
            const variantUrl = new URL(next, url).href;
            variants.push({
                url: variantUrl,
                width,
                height,
                bitrate,
                quality,
                resolution: width > 0 && height > 0 ? `${width}x${height}` : '',
                master: false,
            });
        }
        return variants;
    } catch {
        return [];
    }
}

async function collectStreamVariants(video, resolvedUrl) {
    const dedup = new Map();
    const push = (raw, fallback = {}) => {
        const normalized = normalizeStreamVariant(raw, fallback);
        if (!normalized || !normalized.url) return;
        const prev = dedup.get(normalized.url);
        if (!prev) {
            dedup.set(normalized.url, normalized);
            return;
        }
        const prevScore = getVariantRank(prev, video);
        const nextScore = getVariantRank(normalized, video);
        if (nextScore >= prevScore) dedup.set(normalized.url, { ...prev, ...normalized });
    };

    const initialArrays = [video?.qualityVariants, video?.qualities, video?.sources, video?.streams];
    initialArrays.forEach((arr) => {
        if (!Array.isArray(arr)) return;
        arr.forEach((entry) => push(entry));
    });

    if (resolvedUrl) {
        push({
            url: resolvedUrl,
            quality: video?.quality || '',
            resolution: video?.resolution || '',
            sizeBytes: getVideoSizeBytes(video),
            master: /\.m3u8(?:[?#]|$)/i.test(resolvedUrl),
        });
    }

    const m3u8Candidates = [resolvedUrl, video?.directUrl, video?.url]
        .map((x) => String(x || '').trim())
        .filter((x, idx, arr) => x && arr.indexOf(x) === idx && x.includes('.m3u8'));

    for (const masterUrl of m3u8Candidates) {
        const fromMaster = await fetchHlsMasterVariants(masterUrl, video?.source_url || video?.url || '');
        fromMaster.forEach((variant) => push(variant));
    }

    const list = Array.from(dedup.values()).sort((a, b) => {
        return getVariantRank(b, video) - getVariantRank(a, video);
    });

    return list;
}

async function openVideoModal(video) {
    if (!isPlayableVideoEntry(video)) {
        showToast('Táto položka nie je prehrateľné video.');
        return;
    }

    const modal = document.getElementById('video-modal');
    const videoEl = document.getElementById('modal-video');
    const titleEl = document.getElementById('modal-video-title');
    const hostEl = document.getElementById('modal-video-host');
    const qualityEl = document.getElementById('modal-video-quality');
    const sizeEl = document.getElementById('modal-video-size');
    const qualitySelectEl = document.getElementById('modal-video-quality-select');
    const copyDirectEl = document.getElementById('modal-copy-direct-btn');
    const openDirectEl = document.getElementById('modal-open-direct-btn');
    const zoomInEl = document.getElementById('modal-zoom-in-btn');
    const zoomOutEl = document.getElementById('modal-zoom-out-btn');
    const zoomResetEl = document.getElementById('modal-zoom-reset-btn');
    const loader = document.getElementById('video-loader');
    const loaderStatusEl = document.getElementById('video-loader-status');
    const loaderDetailEl = document.getElementById('video-loader-detail');
    const loaderRetryEl = document.getElementById('video-loader-retry');

    if (!modal || !videoEl) return;
    modalZoomLevel = 1;
    videoEl.style.transformOrigin = 'center center';
    videoEl.style.transform = 'scale(1)';
    videoEl.style.transition = 'transform 120ms ease';

    titleEl.textContent = video.title || 'Video Preview';
    hostEl.textContent = `Host: ${getVideoHost(video)}`;
    qualityEl.textContent = video.quality || 'HD';
    sizeEl.textContent = `Size: ${formatSizeCompact(getVideoSizeBytes(video)) || 'unknown'}`;

    const dateEl = document.getElementById('modal-video-date');
    const taxonomyEl = document.getElementById('modal-video-taxonomy');
    const uploadDateLabel = video.uploadDateLabel || formatDateCompact(video.uploadDate);
    if (dateEl) {
        dateEl.textContent = uploadDateLabel ? `📅 ${uploadDateLabel}` : '';
    }
    if (taxonomyEl) {
        taxonomyEl.innerHTML = '';
        const categories = Array.isArray(video.categories) ? video.categories : (typeof video.categories === 'string' ? video.categories.split(',').map(s => s.trim()).filter(Boolean) : []);
        const tags = Array.isArray(video.tags) ? video.tags : (typeof video.tags === 'string' ? video.tags.split(',').map(s => s.trim()).filter(Boolean) : []);
        categories.forEach(cat => {
            const span = document.createElement('span');
            span.textContent = cat;
            span.style.cssText = 'background:rgba(113,225,255,0.15);color:#71e1ff;border:1px solid rgba(113,225,255,0.4);border-radius:4px;padding:2px 6px;font-size:0.68rem;font-weight:bold;cursor:pointer;';
            span.title = 'Filtrovať kategóriu';
            span.addEventListener('click', () => {
                const catInput = document.getElementById('category-filter');
                if (catInput) {
                    catInput.value = cat;
                    catInput.dispatchEvent(new Event('input', { bubbles: true }));
                }
                modal.style.display = 'none';
                if (window._hls) {
                    window._hls.destroy();
                    window._hls = null;
                }
                videoEl.pause();
                applyFilters();
            });
            taxonomyEl.appendChild(span);
        });
        tags.forEach(tag => {
            const span = document.createElement('span');
            span.textContent = tag;
            span.style.cssText = 'background:rgba(255,255,255,0.06);color:#ccc;border:1px solid rgba(255,255,255,0.16);border-radius:4px;padding:2px 6px;font-size:0.68rem;cursor:pointer;';
            span.title = 'Filtrovať tag';
            span.addEventListener('click', () => {
                const tagInput = document.getElementById('tag-filter');
                if (tagInput) {
                    tagInput.value = tag;
                    tagInput.dispatchEvent(new Event('input', { bubbles: true }));
                }
                modal.style.display = 'none';
                if (window._hls) {
                    window._hls.destroy();
                    window._hls = null;
                }
                videoEl.pause();
                applyFilters();
            });
            taxonomyEl.appendChild(span);
        });
    }

    modalStreamVariants = [];
    modalCurrentStreamUrl = '';
    if (qualitySelectEl) {
        qualitySelectEl.innerHTML = '<option value="">Kvalita: auto</option>';
        qualitySelectEl.disabled = true;
    }
    if (copyDirectEl) copyDirectEl.disabled = true;
    if (openDirectEl) openDirectEl.disabled = true;

    modal.style.display = 'flex';
    loader.style.display = 'flex';
    loader.classList.remove('is-error');
    videoEl.style.opacity = '0';
    const setResolveStatus = (message, detail = 'Modal môže zostať otvorený — prehrávanie sa spustí automaticky.') => {
        if (loaderStatusEl) loaderStatusEl.textContent = message;
        if (loaderDetailEl) loaderDetailEl.textContent = detail;
    };
    const setResolveError = (message) => {
        loader.style.display = 'flex';
        loader.classList.add('is-error');
        setResolveStatus(message, 'Zdroj mohol vypršať alebo byť odstránený. Môžeš spustiť nový pokus.');
    };
    setResolveStatus(isFilesterVideo(video) ? 'Pripravujem Filester video…' : 'Hľadám prehrateľný stream…');
    if (loaderRetryEl) {
        loaderRetryEl.onclick = () => openVideoModal(video);
    }

    // Stop and destroy previous Hls instance
    if (window._hls) {
        window._hls.destroy();
        window._hls = null;
    }
    // Stream resolution is asynchronous, so the click that opened the modal is
    // no longer a user gesture when playback starts. Muted preview is allowed
    // by Chrome; the player controls still let the user enable audio.
    videoEl.muted = true;
    videoEl.defaultMuted = true;
    videoEl.setAttribute('muted', '');
    videoEl.pause();
    videoEl.src = '';
    videoEl.load();

    await tryFindDashboardUrl();

    let streamUrl = null;
    try {
        streamUrl = await resolveVideoUrl(video, setResolveStatus);
    } catch (error) {
        setResolveError(error?.message || 'Stream sa nepodarilo obnoviť.');
        showToast(error?.message || 'Stream sa nepodarilo obnoviť.', 6000);
        return;
    }
    if (!streamUrl) {
        setResolveError('Nepodarilo sa nájsť prehrateľný video zdroj.');
        showToast('Nepodarilo sa nájsť prehrateľný video zdroj.');
        return;
    }

    setResolveStatus('Direct URL nájdená. Pripravujem prehrávanie…');

    const formatVariantLabel = (variant, index) => {
        const quality = String(variant?.quality || qualityLabelFromHeight(variant?.height || 0) || '').trim();
        const resolution = String(variant?.resolution || '').trim();
        const bitrate = Number(variant?.bitrate || 0) || 0;
        const bitrateLabel = bitrate > 0 ? `${(bitrate / 1000000).toFixed(1)} Mbps` : '';
        const rawSizeBytes = Number(variant?.sizeBytes || 0) || 0;
        const sizeLabel = isBogusStreamSize(rawSizeBytes, variant, video) ? '' : formatSizeCompact(rawSizeBytes);
        const parts = [quality, resolution, bitrateLabel, sizeLabel].filter(Boolean);
        return parts.length ? parts.join(' · ') : `Variant ${index + 1}`;
    };

    const syncModalDirectButtons = () => {
        const fallbackDirect = getCopyableDirectUrl(video);
        const hasDirect = !isForumTurboVideo(video) && !!String(modalCurrentStreamUrl || fallbackDirect || streamUrl || '').trim();
        if (copyDirectEl) copyDirectEl.disabled = !hasDirect;
        if (openDirectEl) openDirectEl.disabled = !hasDirect;
    };

    modalStreamVariants = await collectStreamVariants(video, streamUrl);
    if (!modalStreamVariants.length) {
        modalStreamVariants = [{
            url: streamUrl,
            quality: video.quality || '',
            resolution: video.resolution || '',
            sizeBytes: getVideoSizeBytes(video),
            bitrate: 0,
            height: inferVariantHeight(video.quality || streamUrl),
        }];
    }

    if (qualitySelectEl) {
        qualitySelectEl.innerHTML = '';
        modalStreamVariants.forEach((variant, idx) => {
            const option = document.createElement('option');
            option.value = variant.url;
            option.textContent = formatVariantLabel(variant, idx);
            qualitySelectEl.appendChild(option);
        });
        qualitySelectEl.disabled = modalStreamVariants.length <= 1;
        if (modalStreamVariants[0]?.url) {
            streamUrl = modalStreamVariants[0].url;
            video.directUrl = streamUrl;
        }
        qualitySelectEl.value = streamUrl;
    }

    const startPlayback = (label) => {
        const playback = videoEl.play();
        if (!playback || typeof playback.catch !== 'function') return;
        playback.catch((error) => {
            // load(), a quality switch, or closing the modal aborts an earlier
            // play() request. This is expected and must not pollute Errors.
            if (error?.name === 'AbortError') return;
            if (error?.name === 'NotAllowedError') {
                setResolveStatus('Prehliadač čaká na kliknutie Play.', 'Stream je pripravený; prehrávanie spustíš tlačidlom v prehrávači.');
                return;
            }
            console.warn(`${label} failed:`, error);
        });
    };

    const setupVideo = (url) => {
        loader.classList.remove('is-error');
        loader.style.display = 'flex';
        setResolveStatus('Načítavam video stream…', 'Prvé dáta môžu pri veľkom súbore trvať pár sekúnd.');
        modalCurrentStreamUrl = String(url || '').trim();
        const activeVariant = modalStreamVariants.find((variant) => variant.url === modalCurrentStreamUrl) || null;
        const activeQuality = activeVariant?.quality || qualityLabelFromHeight(activeVariant?.height || 0) || video.quality || 'HD';
        const activeSizeBytes = Number(activeVariant?.sizeBytes || 0) || 0;
        const activeSizeLabel = (
            activeVariant && !isBogusStreamSize(activeSizeBytes, activeVariant, video)
                ? formatSizeCompact(activeSizeBytes)
                : ''
        ) || formatSizeCompact(getVideoSizeBytes(video)) || 'unknown';
        qualityEl.textContent = activeQuality;
        sizeEl.textContent = `Size: ${activeSizeLabel}`;
        video.directUrl = modalCurrentStreamUrl;

        if (qualitySelectEl && modalCurrentStreamUrl) {
            qualitySelectEl.value = modalCurrentStreamUrl;
        }
        syncModalDirectButtons();

        const isHls = url.includes('.m3u8') || url.includes('playlist.m3u8');

        if (isHls && typeof Hls !== 'undefined') {
            if (Hls.isSupported()) {
                const hls = new Hls({
                    enableWorker: true,
                    lowLatencyMode: true,
                });
                hls.loadSource(url);
                hls.attachMedia(videoEl);
                hls.on(Hls.Events.MANIFEST_PARSED, () => {
                    startPlayback('HLS playback');
                });
                hls.on(Hls.Events.ERROR, (event, data) => {
                    if (
                        data.fatal &&
                        DASHBOARD_REACHABLE &&
                        !url.includes('/api/v1/proxy') &&
                        !String(url).startsWith('http://localhost:8001/api/v1/proxy') &&
                        !String(url).startsWith('http://localhost:8001/api/v1/proxy') &&
                        !String(url).startsWith('http://localhost:8002/api/v1/proxy') &&
                        !String(url).startsWith('http://localhost:8003/api/v1/proxy') &&
                        !String(url).startsWith('http://localhost:8004/api/v1/proxy') &&
                        !String(url).startsWith('http://localhost:8005/api/v1/proxy')
                    ) {
                        console.log('HLS fatal error, retrying with proxy...');
                        const proxyUrl = `${DASHBOARD_URL}/api/v1/proxy?url=${encodeURIComponent(url)}`;
                        hls.loadSource(proxyUrl);
                    }
                });
                window._hls = hls;
            } else if (videoEl.canPlayType('application/vnd.apple.mpegurl')) {
                videoEl.src = url;
                startPlayback('Native HLS playback');
            }
        } else {
            videoEl.src = url;
            videoEl.load();
            startPlayback('Auto-play');
        }
    };

    videoEl.onloadeddata = () => {
        loader.style.display = 'none';
        loader.classList.remove('is-error');
        videoEl.style.opacity = '1';
    };

    if (qualitySelectEl) {
        qualitySelectEl.onchange = () => {
            const chosenUrl = String(qualitySelectEl.value || '').trim();
            if (!chosenUrl || chosenUrl === modalCurrentStreamUrl) return;
            loader.style.display = 'flex';
            streamUrl = chosenUrl;
            setupVideo(streamUrl);
        };
    }

    if (copyDirectEl) {
        copyDirectEl.onclick = async () => {
            const url = modalCurrentStreamUrl || getCopyableDirectUrl(video) || streamUrl || '';
            if (!url || isForumTurboVideo(video)) return;
            const title = String(video.title || video.originalTitle || 'Video').replace(/[\\/:*?"<>|]/g, '_').trim();
            const text = `${title}.mp4\n${url}#filename=${encodeURIComponent(title)}.mp4`;
            try {
                await navigator.clipboard.writeText(text);
                showToast('✅ Priamy URL s názvom skopírovaný', 2200);
            } catch {
                showToast('Nepodarilo sa skopírovať direct URL', 2200);
            }
        };
    }

    if (openDirectEl) {
        openDirectEl.onclick = () => {
            const value = modalCurrentStreamUrl || getCopyableDirectUrl(video) || streamUrl || '';
            if (!value || isForumTurboVideo(video)) return;
            chrome.tabs.create({ url: value });
        };
    }
    const applyZoom = () => {
        modalZoomLevel = Math.max(1, Math.min(3, modalZoomLevel));
        videoEl.style.transform = `scale(${modalZoomLevel.toFixed(2)})`;
    };
    if (zoomInEl) zoomInEl.onclick = () => { modalZoomLevel += 0.15; applyZoom(); };
    if (zoomOutEl) zoomOutEl.onclick = () => { modalZoomLevel -= 0.15; applyZoom(); };
    if (zoomResetEl) zoomResetEl.onclick = () => { modalZoomLevel = 1; applyZoom(); };
    videoEl.onwheel = (e) => {
        if (!e.ctrlKey) return;
        e.preventDefault();
        modalZoomLevel += e.deltaY < 0 ? 0.08 : -0.08;
        applyZoom();
    };

    let didFreshCamwhoresRetry = false;
    let didBackgroundCamwhoresRetry = false;
    let didBackendCamwhoresRetry = false;
    let didProxyRetry = false;
    videoEl.onerror = async () => {
        const sourceUrl = String(video.source_url || video.url || '');
        if (!didFreshCamwhoresRetry && /camwhores\.tv\/videos\/\d+/i.test(sourceUrl)) {
            didFreshCamwhoresRetry = true;
            const meta = await resolveCamwhoresMetadata(sourceUrl, { force: true });
            if (meta?.playbackUrl && meta.playbackUrl !== streamUrl) {
                console.log('Video load failed, retrying fresh CamWhores stream...');
                applyCamwhoresMetadataToVideo(video, meta);
                streamUrl = meta.playbackUrl;
                video.directUrl = streamUrl;
                setupVideo(streamUrl);
                return;
            }
        }

        if (!didBackgroundCamwhoresRetry && /camwhores\.tv\/videos\/\d+/i.test(sourceUrl)) {
            didBackgroundCamwhoresRetry = true;
            const bgUrl = await resolveCamwhoresDirectViaBackground(sourceUrl);
            if (bgUrl && bgUrl !== streamUrl) {
                console.log('Video load failed, retrying background CamWhores stream...');
                streamUrl = bgUrl;
                video.directUrl = streamUrl;
                setupVideo(streamUrl);
                return;
            }
        }

        if (!didBackendCamwhoresRetry && /camwhores\.tv\/videos\/\d+/i.test(sourceUrl)) {
            didBackendCamwhoresRetry = true;
            const backendUrl = await resolveCamwhoresDirectViaBackend(sourceUrl, video.title || '');
            if (backendUrl && backendUrl !== streamUrl) {
                console.log('Video load failed, retrying backend CamWhores stream...');
                streamUrl = backendUrl;
                video.directUrl = streamUrl;
                setupVideo(streamUrl);
                return;
            }
        }

        const currentSrc = String(videoEl.currentSrc || videoEl.src || '');
        const targetSrc = String(streamUrl || '');
        const alreadyProxy = currentSrc.includes('/api/v1/proxy') || targetSrc.includes('/api/v1/proxy');
        const targetIsLocalProxy = /^https?:\/\/localhost:\d+\/api\/v1\/proxy\?/i.test(targetSrc);
        const avoidProxy = shouldAvoidProxyRetry(targetSrc);
        if (!didProxyRetry && DASHBOARD_REACHABLE && !alreadyProxy && !targetIsLocalProxy && !avoidProxy) {
            didProxyRetry = true;
            console.log('Video load failed, trying dashboard proxy...');
            setResolveStatus('Priamy stream odmietol prehrávanie. Skúšam Nexus proxy…');
            const proxyUrl = `${DASHBOARD_URL}/api/v1/proxy?url=${encodeURIComponent(targetSrc)}`;
            videoEl.src = proxyUrl;
            videoEl.load();
            startPlayback('Proxy playback');
            return;
        }

        if (avoidProxy) {
            showToast('Host blokuje proxy (403). Skús Direct znova pre deep host resolve.', 4200);
            setResolveError('Host odmietol priame aj proxy prehrávanie.');
            return;
        }

        setResolveError('Stream sa našiel, ale prehrávanie zlyhalo.');
        showToast('Prehrávanie zlyhalo. Skús kliknúť Direct alebo spustiť scan znova.', 4500);
    };

    setupVideo(streamUrl);

    // Close on Escape
    const escHandler = (e) => {
        if (e.key === 'Escape') closeVideoModal();
    };
    window.addEventListener('keydown', escHandler, { once: true });
    modal._escHandler = escHandler;

    // Close on click outside
    modal.onclick = (e) => {
        if (e.target === modal) closeVideoModal();
    };
}

function closeVideoModal() {
    const modal = document.getElementById('video-modal');
    const videoEl = document.getElementById('modal-video');
    const qualitySelectEl = document.getElementById('modal-video-quality-select');
    const copyDirectEl = document.getElementById('modal-copy-direct-btn');
    const openDirectEl = document.getElementById('modal-open-direct-btn');
    const loader = document.getElementById('video-loader');
    const loaderRetryEl = document.getElementById('video-loader-retry');
    if (!modal || !videoEl) return;

    if (window._hls) {
        window._hls.destroy();
        window._hls = null;
    }

    videoEl.pause();
    videoEl.src = '';
    videoEl.onwheel = null;
    modalZoomLevel = 1;
    videoEl.style.transform = 'scale(1)';
    modal.style.display = 'none';
    if (loader) loader.classList.remove('is-error');
    if (loaderRetryEl) loaderRetryEl.onclick = null;

    modalCurrentStreamUrl = '';
    modalStreamVariants = [];
    if (qualitySelectEl) {
        qualitySelectEl.onchange = null;
        qualitySelectEl.innerHTML = '<option value="">Kvalita: auto</option>';
        qualitySelectEl.disabled = true;
    }
    if (copyDirectEl) {
        copyDirectEl.onclick = null;
        copyDirectEl.disabled = true;
    }
    if (openDirectEl) {
        openDirectEl.onclick = null;
        openDirectEl.disabled = true;
    }

    if (modal._escHandler) {
        window.removeEventListener('keydown', modal._escHandler);
        delete modal._escHandler;
    }
}

function formatViews(n) {
    if (n >= 1000000) return (n / 1000000).toFixed(1) + 'M';
    if (n >= 1000) return (n / 1000).toFixed(1) + 'K';
    return n.toString();
}

function formatTime(seconds) {
    if (!seconds) return "";
    const h = Math.floor(seconds / 3600);
    const m = Math.floor((seconds % 3600) / 60);
    const s = Math.floor(seconds % 60);
    if (h > 0) {
        return `${h}:${m.toString().padStart(2, '0')}:${s.toString().padStart(2, '0')}`;
    }
    return `${m}:${s.toString().padStart(2, '0')}`;
}

function formatSizeCompact(bytes) {
    const val = Number(bytes || 0);
    if (!val || val <= 0) return '';
    if (val >= 1073741824) return `${(val / 1073741824).toFixed(1)} GB`;
    if (val >= 1048576) return `${(val / 1048576).toFixed(1)} MB`;
    if (val >= 1024) return `${(val / 1024).toFixed(1)} KB`;
    return `${val} B`;
}

function parseAnySizeToBytes(value) {
    if (value == null || value === '') return 0;
    if (typeof value === 'number' && Number.isFinite(value) && value > 0) {
        if (!Number.isInteger(value) && value < 32768) {
            return Math.round(value * 1048576);
        }
        return Math.round(value);
    }
    const text = String(value).trim().replace(',', '.');
    if (!text) return 0;
    const unitMatch = text.match(/([\d.]+)\s*(TB|GB|MB|KB|B)\b/i);
    if (unitMatch) {
        const amount = parseFloat(unitMatch[1]);
        const unit = (unitMatch[2] || 'B').toUpperCase();
        const mult = { B: 1, KB: 1024, MB: 1048576, GB: 1073741824, TB: 1099511627776 };
        return Number.isFinite(amount) && amount > 0 ? Math.round(amount * (mult[unit] || 1)) : 0;
    }
    const plain = Number(text);
    return Number.isFinite(plain) && plain > 0 ? Math.round(plain) : 0;
}

function getVideoSizeBytes(video) {
    if (!video || typeof video !== 'object') return 0;
    if (isFaphouseVideo(video)) {
        return video.faphouseResolverVersion === 2 && video.sizeStreamUrl === video.directUrl
            ? Number(video.size || 0) : 0;
    }

    let stats = video.download_stats;
    if (typeof stats === 'string') {
        try {
            stats = JSON.parse(stats);
        } catch {
            stats = null;
        }
    }

    const mbCandidates = [video.file_size_mb, video.size_mb, stats?.size_mb];
    for (const candidate of mbCandidates) {
        const mb = parseFloat(candidate);
        if (Number.isFinite(mb) && mb > 0) {
            const bytes = Math.round(mb * 1048576);
            if (!isBogusStreamSize(bytes, {}, video)) return bytes;
        }
    }

    const byteCandidates = [
        video.size_bytes,
        video.size,
        video.filesize,
        video.file_size_bytes,
        video.filesize_bytes,
        video.reported_size_bytes,
        stats?.reported_size_bytes,
    ];
    for (const candidate of byteCandidates) {
        const bytes = parseAnySizeToBytes(candidate);
        if (bytes > 0 && !isBogusStreamSize(bytes, {}, video)) return bytes;
    }

    return 0;
}

function getVideoSizeMegabytes(video) {
    const bytes = getVideoSizeBytes(video);
    return bytes > 0 ? Number((bytes / 1048576).toFixed(2)) : 0;
}

function normalizeVideoSizeFields(video) {
    if (!video || typeof video !== 'object') return video;
    const bytes = getVideoSizeBytes(video);
    if (bytes > 0) {
        video.size = bytes;
        if (!Number(video.size_bytes || 0)) video.size_bytes = bytes;
        if (!Number(video.filesize || 0)) video.filesize = bytes;
        if (!Number(video.file_size_mb || 0)) video.file_size_mb = Number((bytes / 1048576).toFixed(2));
    }
    return video;
}

function mapCamwhoresFastExportToVideos(payload) {
    const items = Array.isArray(payload?.items) ? payload.items : [];
    const mapped = [];
    for (const item of items) {
        const sourceUrl = String(item?.source_url || item?.url || '').trim();
        if (!sourceUrl) continue;
        const directUrl = String(item?.directUrl || '').trim();
        const sizeBytes = Number(item?.sizeBytes || item?.size || 0) || 0;
        const height = Number(item?.height || 0) || 0;
        const width = Number(item?.width || 0) || 0;
        const quality = String(item?.quality || (height > 0 ? `${height}p` : '?')).trim() || '?';
        const duration = Number(item?.duration || 0) || parseDuration(item?.durationText || '');
        mapped.push(normalizeVideoSizeFields({
            id: String(item?.id || sourceUrl),
            title: String(item?.title || 'CamWhores video').trim(),
            url: sourceUrl,
            source_url: sourceUrl,
            directUrl: directUrl || undefined,
            thumbnail: String(item?.thumbnail || '').trim() || 'MISSING_THUMBNAIL',
            duration: duration || 0,
            quality,
            width,
            height,
            size: sizeBytes,
            size_bytes: sizeBytes,
            views: String(item?.views || '').trim() || null,
            context: 'Camwhores Fast Bridge',
        }));
    }
    return mapped;
}

function loadCamwhoresFastExportIntoGallery(payload, sourceLabel = 'userscript') {
    const rows = mapCamwhoresFastExportToVideos(payload);
    if (!rows.length) {
        showToast('CW Fast export je prázdny.', 2400);
        return 0;
    }
    allVideos = rows;
    currentlyFilteredVideos = [...allVideos];
    selectedVideos.clear();
    const folderEl = document.getElementById('folder-name');
    if (folderEl) {
        const mode = String(payload?.mode || 'unknown');
        const profile = String(payload?.profile || 'fast').toUpperCase();
        folderEl.innerText = `CamWhores Fast (${mode}/${profile})`;
    }
    applyFilters();
    updateStats();
    setBunkrBridgeLog(`CW Fast export loaded (${sourceLabel}): ${rows.length} rows.`);
    showToast(`CW Fast export načítaný: ${rows.length} videí`, 2800);
    return rows.length;
}

function normalizeQualityLabel(value, options = {}) {
    const allowUnknown = options.allowUnknown !== false;
    const raw = String(value || '').trim();
    if (!raw) return allowUnknown ? '?' : '';
    if (/^\d+$/.test(raw)) return allowUnknown ? '?' : '';
    const upper = raw.toUpperCase();
    if (upper === '?' || upper === 'UNKNOWN') return allowUnknown ? '?' : '';
    if (upper === '4K' || upper === 'UHD') return '4K';
    if (/^2160P?$/i.test(raw)) return '4K';
    if (/^1440P?$/i.test(raw)) return '1440p';
    if (/^1080P?$/i.test(raw)) return '1080p';
    if (/^720P?$/i.test(raw)) return '720p';
    if (/^480P?$/i.test(raw)) return '480p';
    if (/^360P?$/i.test(raw)) return '360p';
    if (/^240P?$/i.test(raw)) return '240p';
    if (/^HD\??$/i.test(raw)) return allowUnknown && raw.includes('?') ? 'HD?' : 'HD';
    return raw;
}

function getDisplayQualityLabel(video) {
    if (/camwhores\.tv/i.test(String(video?.source_url || video?.url || ''))) {
        const exact = normalizeQualityLabel(video?.quality || '', { allowUnknown: false });
        if (exact && exact !== 'HD' && exact !== 'HD?') return exact;
    }
    const fromHeight = qualityLabelFromHeight(Number(video?.height || 0));
    const fromResolution = inferQualityLabelFromText(video?.resolution || '');
    return normalizeQualityLabel(fromHeight || fromResolution || video?.quality || '', { allowUnknown: true });
}

function getImportQualityLabel(video) {
    const label = normalizeQualityLabel(getDisplayQualityLabel(video), { allowUnknown: false });
    if (!label || label === '?' || label === 'HD?') return null;
    return label;
}

function inferExplicitQualityLabel(text) {
    const t = String(text || '').toUpperCase();
    if (/\b(4K|2160P|UHD)\b/.test(t)) return '4K';
    if (/\b(1440P|2K)\b/.test(t)) return '1440p';
    if (/\b(1080P|FHD|FULL\s?HD)\b/.test(t)) return '1080p';
    if (/\b720P\b/.test(t)) return '720p';
    if (/\b480P\b/.test(t)) return '480p';
    if (/\b360P\b/.test(t)) return '360p';
    if (/\b240P\b/.test(t)) return '240p';
    return '';
}

function formatDateCompact(value) {
    if (!value) return '';
    const d = new Date(value);
    if (Number.isNaN(d.getTime())) return String(value).trim();
    return d.toLocaleDateString(undefined, { year: 'numeric', month: 'short', day: '2-digit' });
}

function parseLooseDateEpoch(rawValue) {
    if (typeof rawValue === 'number' && Number.isFinite(rawValue)) {
        return rawValue > 1e12 ? rawValue : rawValue * 1000;
    }

    const raw = String(rawValue || '').trim();
    if (!raw) return 0;

    const normalized = raw.replace(/\s+/g, ' ').trim();
    const timeMatch = normalized.match(/\b(\d{1,2}):(\d{2})(?::(\d{2}))?\b/);
    const timeToken = timeMatch?.[0] || '';

    let y = 0;
    let m = 0;
    let d = 0;

    const ymdMatch = normalized.match(/\b(\d{4})[./-](\d{1,2})[./-](\d{1,2})\b/);
    const dmyMatch = normalized.match(/\b(\d{1,2})[./-](\d{1,2})[./-](\d{4})\b/);

    if (ymdMatch) {
        y = parseInt(ymdMatch[1], 10) || 0;
        m = parseInt(ymdMatch[2], 10) || 0;
        d = parseInt(ymdMatch[3], 10) || 0;
    } else if (dmyMatch) {
        d = parseInt(dmyMatch[1], 10) || 0;
        m = parseInt(dmyMatch[2], 10) || 0;
        y = parseInt(dmyMatch[3], 10) || 0;
    }

    if (y >= 1970 && y <= 2200 && m >= 1 && m <= 12 && d >= 1 && d <= 31) {
        let hh = 0;
        let mm = 0;
        let ss = 0;
        if (timeToken) {
            const parts = timeToken.split(':').map((x) => parseInt(x, 10));
            hh = parts[0] || 0;
            mm = parts[1] || 0;
            ss = parts[2] || 0;
        }
        const ts = new Date(y, m - 1, d, hh, mm, ss).getTime();
        if (Number.isFinite(ts) && ts > 0) return ts;
    }

    const nativeParsed = new Date(normalized).getTime();
    return Number.isFinite(nativeParsed) && nativeParsed > 0 ? nativeParsed : 0;
}

function parseVideoDateEpoch(video) {
    const candidates = [
        video?.uploadDate,
        video?.uploadDateLabel,
        video?.duration,
        video?.timestamp,
        video?.date,
        video?.created_at,
        video?.createdAt,
        video?.publishedAt,
        video?.datePublished,
    ];

    for (const candidate of candidates) {
        const parsed = parseLooseDateEpoch(candidate);
        if (parsed > 0) return parsed;
    }
    return 0;
}

function isDateLikeMetadataText(value) {
    const text = String(value || '');
    return (
        /\b\d{4}[./-]\d{1,2}[./-]\d{1,2}\b/.test(text) ||
        /\b\d{1,2}[./-]\d{1,2}[./-]\d{2,4}\b/.test(text)
    );
}

function getSortableDurationSeconds(video) {
    const numericCandidates = [
        video?.durationSeconds,
        video?.duration_seconds,
        video?.durationSec,
        video?.lengthSeconds,
        video?.length_seconds,
    ];
    for (const candidate of numericCandidates) {
        const value = Number(candidate || 0);
        if (Number.isFinite(value) && value > 0) return value;
    }
    if (typeof video?.duration === 'number') return Number(video.duration || 0);
    if (isDateLikeMetadataText(video?.duration)) return 0;
    return parseDuration(video?.duration);
}

function splitFilterTerms(value) {
    return String(value || '')
        .toLowerCase()
        .split(',')
        .map((x) => x.trim())
        .filter(Boolean);
}

function setCommaSeparatedFilter(id, term) {
    const input = document.getElementById(id);
    if (!input) return;
    const next = term.toLowerCase().trim();
    if (!next) return;
    const terms = splitFilterTerms(input.value);
    const idx = terms.indexOf(next);
    if (idx >= 0) terms.splice(idx, 1);
    else terms.push(next);
    input.value = terms.join(', ');
}

function setQualityFilterValue(value) {
    const token = String(value || '').trim();
    const box = document.querySelector(`.quality-opt[value="${CSS.escape(token)}"]`);
    if (!box) return;
    box.checked = !box.checked;
}

function normalizeTextTokens(value) {
    return String(value || '')
        .toLowerCase()
        .split(/[;,|/]+/)
        .map((x) => x.trim())
        .filter(Boolean);
}

function buildFrequencyMap(items, getter) {
    const map = new Map();
    for (const item of items || []) {
        const values = normalizeTextTokens(getter(item));
        for (const value of values) {
            map.set(value, (map.get(value) || 0) + 1);
        }
    }
    return map;
}

function topEntriesByCount(map, limit = 10) {
    return Array.from(map.entries())
        .sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0]))
        .slice(0, limit);
}

function renderQuickFilters() {
    const host = document.getElementById('quick-filters');
    if (!host) return;

    const qualityBoxes = Array.from(document.querySelectorAll('.quality-opt'));
    const activeQualityTokens = new Set(qualityBoxes.filter((el) => el.checked).map((el) => String(el.value || '').trim()));
    const missingMetaActive = !!document.getElementById('missing-meta-filter')?.checked;
    const categoryTerms = splitFilterTerms(document.getElementById('category-filter')?.value || '');
    const tagTerms = splitFilterTerms(document.getElementById('tag-filter')?.value || '');

    const tagMap = buildFrequencyMap(allVideos, (v) => v.tags);
    const categoryMap = buildFrequencyMap(allVideos, (v) => v.categories || v.category);
    const topTags = topEntriesByCount(tagMap, 10);
    const topCategories = topEntriesByCount(categoryMap, 10);
    const qualityOrder = [
        ['2160', '2160p'],
        ['1440', '1440p'],
        ['1080', '1080p'],
        ['720', '720p'],
        ['480', '480p'],
        ['360', '360p'],
        ['240', '240p'],
        ['unknown', '?'],
    ];

    const button = (label, attrs = {}) => {
        const active = attrs.active ? ' active' : '';
        const clear = attrs.clear ? ' clear' : '';
        const title = attrs.title ? ` title="${attrs.title}"` : '';
        const kind = attrs.kind ? ` data-kind="${attrs.kind}"` : '';
        const value = attrs.value ? ` data-value="${attrs.value}"` : '';
        return `<button class="quick-chip${active}${clear}" type="button"${kind}${value}${title}>${label}</button>`;
    };

    const chips = [];
    chips.push('<span class="quick-filter-label">Rýchle filtre</span>');
    qualityOrder.forEach(([value, label]) => {
        chips.push(button(label, {
            kind: 'quality',
            value,
            active: activeQualityTokens.has(value),
            title: `Prepne kvalitu ${label}`,
        }));
    });
    chips.push(button('Vymazať kvality', { kind: 'clear-qualities', clear: true, title: 'Zruší všetky kvality' }));
    const missingCount = (allVideos || []).filter((v) => hasMissingQualityOrSize(v)).length;
    if (missingCount > 0) {
        chips.push(button(`Chýba meta (${missingCount})`, {
            kind: 'missing-meta',
            active: missingMetaActive,
            title: 'Zobrazí videá bez overenej kvality alebo veľkosti',
        }));
    }

    chips.push('<span class="quick-filter-label">Kategórie</span>');
    topCategories.forEach(([label, count]) => {
        chips.push(button(`${label} (${count})`, {
            kind: 'category',
            value: label,
            active: categoryTerms.includes(label),
            title: `Filtrovať podľa kategórie ${label}`,
        }));
    });

    chips.push('<span class="quick-filter-label">Tagy</span>');
    topTags.forEach(([label, count]) => {
        chips.push(button(`${label} (${count})`, {
            kind: 'tag',
            value: label,
            active: tagTerms.includes(label),
            title: `Filtrovať podľa tagu ${label}`,
        }));
    });

    chips.push(button('Vyčistiť všetko', { kind: 'clear-all', clear: true, title: 'Vymaže všetky quick filtre' }));
    host.innerHTML = chips.join('');

    if (host._quickFilterHandler) {
        host.removeEventListener('click', host._quickFilterHandler);
    }
    const handler = (e) => {
        const btn = e.target.closest('.quick-chip');
        if (!btn || !host.contains(btn)) return;
        const kind = btn.dataset.kind || '';
        const value = btn.dataset.value || '';
        if (kind === 'quality') {
            setQualityFilterValue(value);
            applyFilters();
            return;
        }
        if (kind === 'category') {
            setCommaSeparatedFilter('category-filter', value);
            applyFilters();
            return;
        }
        if (kind === 'tag') {
            setCommaSeparatedFilter('tag-filter', value);
            applyFilters();
            return;
        }
        if (kind === 'clear-qualities') {
            qualityBoxes.forEach((el) => { el.checked = false; });
            applyFilters();
            return;
        }
        if (kind === 'missing-meta') {
            const box = document.getElementById('missing-meta-filter');
            if (box) box.checked = !box.checked;
            applyFilters();
            return;
        }
        if (kind === 'clear-all') {
            qualityBoxes.forEach((el) => { el.checked = false; });
            const missingBox = document.getElementById('missing-meta-filter');
            if (missingBox) missingBox.checked = false;
            const categoryInput = document.getElementById('category-filter');
            const tagInput = document.getElementById('tag-filter');
            if (categoryInput) categoryInput.value = '';
            if (tagInput) tagInput.value = '';
            applyFilters();
        }
    };
    host._quickFilterHandler = handler;
    host.addEventListener('click', handler);
}

function toggleSelection(video, card) {
    if (selectedVideos.has(video.id)) {
        selectedVideos.delete(video.id);
        card.classList.remove('selected');
    } else {
        selectedVideos.add(video.id);
        card.classList.add('selected');
    }
    updateStats();
}

function updateStats() {
    const statsText = document.getElementById('stats-text');
    const importBtn = document.getElementById('import-btn');
    const importFilteredBtn = document.getElementById('import-filtered-btn');
    const copyBtn = document.getElementById('copy-btn');
    const copyDirectBtn = document.getElementById('copy-direct-btn');
    const queueBtn = document.getElementById('queue-btn');
    const directScopeChip = document.getElementById('direct-scope-chip');
    const selectAllBtn = document.getElementById('select-all');

    if (statsText) {
        const metaReady = (allVideos || []).filter((v) => {
            const hasQuality = qualityRank(getDisplayQualityLabel(v)) > 0;
            const hasSize = getVideoSizeBytes(v) > 0;
            const hasDirect = !!getCopyableDirectUrl(v);
            return hasQuality && hasSize && hasDirect;
        }).length;
        const metaCoverage = allVideos.length > 0 ? ` | Meta: ${metaReady}/${allVideos.length}` : '';
        const filteredCount = Array.isArray(currentlyFilteredVideos) ? currentlyFilteredVideos.length : 0;
        statsText.innerText = `${allVideos.length} videí | Filter: ${filteredCount} | Vybraných: ${selectedVideos.size}${metaCoverage}`;
    }
    if (importBtn) { importBtn.innerText = `Importovať (${selectedVideos.size})`; importBtn.disabled = selectedVideos.size === 0; }
    if (importFilteredBtn) {
        const filteredCount = Array.isArray(currentlyFilteredVideos) ? currentlyFilteredVideos.length : 0;
        importFilteredBtn.innerText = `Import filter (${filteredCount})`;
        importFilteredBtn.disabled = filteredCount === 0;
    }
    if (copyBtn) copyBtn.disabled = selectedVideos.size === 0;
    if (queueBtn) queueBtn.disabled = selectedVideos.size === 0;
    if (directScopeChip) directScopeChip.textContent = getBackgroundResolutionScopeLabel();
    if (selectAllBtn) {
        const hasSelection = selectedVideos.size > 0;
        selectAllBtn.textContent = hasSelection
            ? `✗ Zrušiť výber (${selectedVideos.size})`
            : '✓ Označiť všetko';
        selectAllBtn.classList.toggle('btn-danger-soft', hasSelection);
        selectAllBtn.classList.toggle('btn-secondary', !hasSelection);
        selectAllBtn.title = hasSelection
            ? 'Zruší všetky aktuálne označené videá'
            : 'Označí všetky aktuálne zobrazené videá';
    }

    // Direct copy button logic
    if (copyDirectBtn) {
        const selectedList = (currentlyFilteredVideos || []).filter(v => selectedVideos.has(v.id));
        const hasAnyDirect = selectedList.some(v => isFaphouseVideo(v) || !!getCopyableDirectUrl(v));
        copyDirectBtn.disabled = !hasAnyDirect;
    }
    const sendJdBtn = document.getElementById('send-jdownloader-btn');
    if (sendJdBtn) {
        const selectedList = (currentlyFilteredVideos || []).filter(v => selectedVideos.has(v.id));
        const hasAnyDirect = selectedList.some(v => isFaphouseVideo(v) || !!getCopyableDirectUrl(v));
        sendJdBtn.disabled = !hasAnyDirect;
        const saveCrawljobBtn = document.getElementById('save-crawljob-btn');
        if (saveCrawljobBtn) saveCrawljobBtn.disabled = !hasAnyDirect;
    }

    // Badge
    const vcBadge = document.getElementById('videos-count-badge');
    if (vcBadge) vcBadge.textContent = allVideos.length;

    const findDirectBtn = document.getElementById('find-direct-btn');
    if (findDirectBtn) {
        findDirectBtn.style.display = (allVideos.length > 0 && !isBackgroundResolving) ? 'block' : 'none';
        findDirectBtn.disabled = selectedVideos.size === 0;
        findDirectBtn.innerText = selectedVideos.size > 0 ? `Direct (${selectedVideos.size} vybraných)` : 'Direct (označ videá)';
    }

    const metaBtn = document.getElementById('fetch-meta-btn');
    if (metaBtn) {
        const pendingMeta = getMetadataTargetVideos().length;
        const profile = getMetaThrottleProfile();
        // Povolíme zobrazenie tlačidla pre akékoľvek video s chýbajúcimi detailmi
        metaBtn.style.display = (pendingMeta > 0 && !isMetadataResolving) ? 'block' : 'none';
        metaBtn.disabled = isMetadataResolving || pendingMeta === 0;
        metaBtn.innerText = pendingMeta > 0 ? `Doplniť meta ${profile.label} (${pendingMeta})` : `Doplniť meta ${profile.label}`;
    }

    const cleanInvalidBtn = document.getElementById('clean-invalid-btn');
    if (cleanInvalidBtn) {
        cleanInvalidBtn.style.display = allVideos.length > 0 ? 'block' : 'none';
        cleanInvalidBtn.disabled = allVideos.length === 0;
    }

    renderQuickFilters();
    updatePageScanInfo();
    syncMissionStatus();
    updateOperationTimersUi();
    scheduleBatchAutosave('stats');
}

function parseDuration(str) {
    if (!str) return 0;
    try {
        const clean = String(str).toLowerCase().trim();
        // Handle cases like "9 min", "9m", "9 min."
        if (clean.includes('min') || (clean.includes('m') && !clean.includes(':'))) {
            const num = parseFloat(clean.replace(/[^\d.]/g, ''));
            if (Number.isFinite(num) && num > 0) {
                return Math.round(num * 60);
            }
        }
        // Handle case like "1 h 20 min" or similar
        if (clean.includes('h') && clean.includes('min')) {
            const hMatch = clean.match(/(\d+)\s*h/);
            const mMatch = clean.match(/(\d+)\s*min/);
            const h = hMatch ? parseInt(hMatch[1], 10) : 0;
            const m = mMatch ? parseInt(mMatch[1], 10) : 0;
            return h * 3600 + m * 60;
        }

        const parts = str.replace(/[^\d:]/g, '').split(':').map(p => parseInt(p, 10));
        if (parts.length === 3) return parts[0] * 3600 + parts[1] * 60 + parts[2];
        if (parts.length === 2) return parts[0] * 60 + parts[1];
        return parts[0] || 0;
    } catch { return 0; }
};

function parseIsoDurationToSeconds(isoText) {
    const m = String(isoText || '').match(/^PT(?:(\d+)H)?(?:(\d+)M)?(?:(\d+)S)?$/i);
    if (!m) return 0;
    const h = parseInt(m[1] || '0', 10);
    const mm = parseInt(m[2] || '0', 10);
    const s = parseInt(m[3] || '0', 10);
    return h * 3600 + mm * 60 + s;
}

function parseLooseSizeToBytes(text) {
    const m = String(text || '').match(/(\d+(?:[.,]\d+)?)\s*(TB|GB|MB|KB|B)\b/i);
    if (!m) return 0;
    const n = parseFloat(m[1].replace(',', '.'));
    const u = m[2].toUpperCase();
    if (!Number.isFinite(n) || n <= 0) return 0;
    const mult = { B: 1, KB: 1024, MB: 1048576, GB: 1073741824, TB: 1099511627776 };
    return Math.round(n * (mult[u] || 1));
}

function inferQualityLabelFromText(text) {
    const t = String(text || '').toUpperCase();
    if (/\b(4K|2160P|UHD)\b/.test(t)) return '4K';
    if (/\b(1440P|2K)\b/.test(t)) return '1440p';
    if (/\b(1080P|FHD|FULL\s?HD)\b/.test(t)) return '1080p';
    if (/\b(720P|HD)\b/.test(t)) return '720p';
    if (/\b(480P|SD)\b/.test(t)) return '480p';
    if (/\b360P\b/.test(t)) return '360p';
    return '';
}

function inferMediaKindFromValues(...values) {
    const joined = values
        .flat()
        .map((value) => String(value || '').trim().toLowerCase())
        .filter(Boolean)
        .join(' | ');

    if (!joined) return '';
    if (/\.(jpe?g|png|gif|webp|avif|bmp|svg)(?:[?#]|$)/i.test(joined) || /\bimage\//i.test(joined)) return 'image';
    if (/\.(mp4|mkv|webm|mov|m4v|avi|m3u8|mpd|ts|m2ts|ogv|vid)(?:[/?#]|$)/i.test(joined) || /\bvideo\//i.test(joined)) return 'video';
    return '';
}

function isPlayableVideoEntry(video) {
    if (!video) return false;
    const explicitType = String(video.mediaType || video.media_type || '').toLowerCase();
    if (explicitType === 'image') return false;
    if (explicitType === 'video') return true;

    const inferred = inferMediaKindFromValues(
        video.title,
        video.filename,
        video.url,
        video.directUrl,
        video.source_url,
        video.bunkr_page_url,
        video.mime,
        video.mime_type,
        video.contentType,
        video.content_type,
    );
    return inferred !== 'image';
}

function looksLikeDirectMediaUrl(url) {
    const value = String(url || '').trim().toLowerCase();
    if (!value) return false;
    if (value.startsWith('blob:')) return true;
    // Streamtape /v/.../name.mp4 is a watch route, not a direct media file.
    if (/streamtape\.[a-z]+\/v\//i.test(value)) return false;
    return /\.(mp4|m3u8|webm|mkv|mov|m4v|avi|mpd|ts|m2ts|ogv|vid)(?:[/?#]|$)/i.test(value);
}

function shouldAvoidProxyRetry(url) {
    const raw = String(url || '').toLowerCase();
    if (!raw) return false;
    if (/tnmr\.org\/hls2\//i.test(raw)) return true;
    if (/trafficdeposit\.com\/.*vidthumb\.mp4/i.test(raw)) return true;
    return false;
}

async function resolveStreamtapeDirect(pageUrl) {
    const url = String(pageUrl || '').trim();
    if (!/streamtape\.[a-z]+\//i.test(url)) return null;
    try {
        const resp = await fetch(url, { credentials: 'include' });
        if (!resp.ok) return null;
        const html = await resp.text();

        const directMatch =
            html.match(/https?:\/\/[^"'\\\s<>]*streamtape[^"'\\\s<>]*\/get_video\?id=[^"'\\\s<>]+/i) ||
            html.match(/id=["']robotlink["'][^>]*href=["']([^"']+)["']/i) ||
            html.match(/href=["']([^"']*\/get_video\?id=[^"']+)["']/i);
        if (!directMatch) return null;
        const raw = String(directMatch[1] || directMatch[0] || '').trim();
        if (!raw) return null;
        const abs = new URL(raw, url).href;
        return /\/get_video\?id=/i.test(abs) ? abs : null;
    } catch {
        return null;
    }
}

function qualityRank(label) {
    const q = String(label || '').toLowerCase();
    if (q === '4k') return 6;
    if (q === '1440p') return 5;
    if (q === '1080p') return 4;
    if (q === '720p') return 3;
    if (q === '480p') return 2;
    if (q === '360p') return 1;
    if (q === '240p') return 0.5;
    return 0;
}

function isHornySimpVideo(video) {
    if (!video) return false;
    const src = String(video.source_url || video.url || '').toLowerCase();
    return src.includes('hornysimp');
}

function isNsfw247Video(video) {
    if (!video) return false;
    const src = String(video.source_url || video.url || '').toLowerCase();
    return src.includes('nsfw247');
}

function isPornHatVideo(video) {
    if (!video) return false;
    const src = String(video.source_url || video.url || '').toLowerCase();
    return src.includes('pornhat.com');
}

function isForumTurboVideo(video) {
    if (!video) return false;
    const source = String(video.source_url || '').toLowerCase();
    const url = String(video.url || '').toLowerCase();
    const direct = String(video.directUrl || '').toLowerCase();
    const hasTurbo = /turbo\.cr\/(?:v|d|embed)\//i.test(`${source} ${url} ${direct}`);
    if (!hasTurbo) return false;
    return /simpcity\.cr|forum|thread|topic|post/i.test(source);
}

function isFaphouseVideo(video) {
    try { return /(^|\.)faphouse\.com$/i.test(new URL(video?.source_url || video?.url || '').hostname); }
    catch { return false; }
}

function isFilesterFilePageUrl(rawUrl) {
    try {
        const parsed = new URL(String(rawUrl || '').trim());
        return /(?:^|\.)filester\.(?:me|gg|net|co|org|io)$/i.test(parsed.hostname)
            && /^\/d\/[A-Za-z0-9_-]+\/?$/i.test(parsed.pathname);
    } catch {
        return false;
    }
}

function isFilesterVideo(video) {
    return isFilesterFilePageUrl(video?.source_url) || isFilesterFilePageUrl(video?.url);
}

function isFilesterPlaybackUrl(rawUrl) {
    const value = String(rawUrl || '').trim();
    if (!value || isFilesterFilePageUrl(value)) return false;
    try {
        const parsed = new URL(value);
        if (/^fsc\d*\.cdn\.cr$/i.test(parsed.hostname) && /\/v\d*\//i.test(parsed.pathname)) return true;
        if (/(?:^|\.)filester\.(?:me|gg|net|co|org|io)$/i.test(parsed.hostname)
            && !/^\/(?:d|f)\//i.test(parsed.pathname)
            && /\/(?:v|video|stream)\//i.test(parsed.pathname)) return true;
    } catch { }
    return looksLikeDirectMediaUrl(value) && !/(?:thumb|preview|sample|trailer)/i.test(value);
}

function applyFilesterResolvedData(video, data = {}) {
    const streamUrl = String(data.stream_url || data.streamUrl || data.directUrl || '').trim();
    if (!isFilesterPlaybackUrl(streamUrl)) return '';
    video.directUrl = streamUrl;
    video.stream_url = streamUrl;
    video.video_url = streamUrl;
    if (data.title && (!video.title || /^filester video$/i.test(String(video.title)))) video.title = data.title;
    if (data.thumbnail && (!video.thumbnail || video.thumbnail === 'MISSING_THUMBNAIL')) video.thumbnail = data.thumbnail;
    if (Number(data.duration || 0) > 0) video.duration = Number(data.duration);
    if (Number(data.width || 0) > 0) video.width = Number(data.width);
    if (Number(data.height || 0) > 0) video.height = Number(data.height);
    if (data.quality) video.quality = data.quality;
    const sizeBytes = Number(data.size_bytes || data.sizeBytes || data.size || 0) || 0;
    if (isUsableVideoSize(sizeBytes, video, streamUrl)) video.size = sizeBytes;
    try { video.playback_host = normalizeHostName(new URL(streamUrl).hostname); } catch { }
    video._metaChecked = true;
    video._metaSuccess = true;
    return streamUrl;
}

async function resolveFilesterVideo(video, onStatus = null) {
    const pageUrl = String(
        [video?.source_url, video?.url].find(isFilesterFilePageUrl) || ''
    ).trim();
    if (!pageUrl) return null;

    const existing = [video.directUrl, video.direct_url, video.stream_url, video.video_url, video.url]
        .map((value) => String(value || '').trim())
        .find(isFilesterPlaybackUrl);
    if (existing) return applyFilesterResolvedData(video, { stream_url: existing });

    onStatus?.('Kontrolujem už zachytený Filester stream…');
    try {
        const captured = await new Promise((resolve) => {
            const timeout = setTimeout(() => resolve(null), 1800);
            chrome.runtime.sendMessage({
                action: 'GET_CAPTURED_STREAM',
                pageUrl,
                duration: Number(video.duration || 0) || 0,
            }, (response) => {
                clearTimeout(timeout);
                const data = response?.data || response || {};
                resolve(response?.ok && data?.playable ? data : null);
            });
        });
        const capturedUrl = applyFilesterResolvedData(video, captured || {});
        if (capturedUrl) return capturedUrl;
    } catch { }

    onStatus?.('Filester: generujem čerstvú Direct URL…');
    const resolved = await new Promise((resolve) => {
        const timeout = setTimeout(() => resolve({ ok: false, error: 'Filester resolver vypršal' }), 22000);
        chrome.runtime.sendMessage({ action: 'FILESTER_RESOLVE_STREAM', pageUrl }, (response) => {
            clearTimeout(timeout);
            if (chrome.runtime.lastError) {
                resolve({ ok: false, error: chrome.runtime.lastError.message });
                return;
            }
            resolve(response || { ok: false });
        });
    });
    const streamUrl = applyFilesterResolvedData(video, resolved || {});
    if (streamUrl) return streamUrl;
    console.warn('[Filester] Player resolver failed:', resolved?.error || 'unknown error');
    return null;
}

async function resolveFaphouseVideo(video, tabId) {
    const pageUrl = video.source_url || video.url;
    // Retire generic cache fields together: their size may refer to the
    // advertised original while their URL refers to a different rendition.
    video.directUrl = '';
    video.faphouseResolverVersion = 0;
    for (const key of ['size', 'sizeBytes', 'size_bytes', 'filesize', 'file_size_bytes', 'filesize_bytes', 'reported_size_bytes', 'file_size_mb', 'size_mb']) video[key] = 0;
    video.sizeStreamUrl = '';
    video.sizeEstimated = false;
    if (!Number.isInteger(tabId)) throw new Error('Otvor zdrojovú FapHouse kartu a obnov Gallery.');
    let response;
    try {
        response = await chrome.tabs.sendMessage(tabId, { action: 'FAPHOUSE_GALLERY_RESOLVE', url: pageUrl, force: true });
    } catch { throw new Error('Obnov FapHouse stránku po obnovení rozšírenia.'); }
    const item = response?.items?.[0];
    if (!response?.ok || !item?.directUrl || item.resolverVersion !== 2) {
        throw new Error(item?.resolveError || response?.error || 'FapHouse zdroj sa nepodarilo overiť. Obnov stránku.');
    }
    const id = new URL(pageUrl).pathname.replace(/\/$/, '').split('/').pop().split('-').pop();
    if (!new URL(item.directUrl).pathname.split('/').includes(id)) {
        throw new Error('ID streamu nesedí s vybraným videom. Export zastavený.');
    }
    video.directUrl = item.directUrl;
    video.faphouseResolvedUrl = item.directUrl;
    video.faphouseResolverVersion = 2;
    video.quality = item.quality || '?';
    video.height = Number(String(item.quality || '').replace(/\D/g, '')) || 0;
    video.width = 0;
    if (item.duration > 0) video.duration = item.duration;
    video.size = Number(item.size || 0);
    video.sizeStreamUrl = item.sizeStreamUrl || '';
    video.sizeEstimated = !!item.sizeEstimated;
    video.uploadDate = item.uploadDate || video.uploadDate;
    video._metaChecked = true;
    video._metaSuccess = true;
    scheduleFaphouseCardCacheSave([video]);
    return item;
}

function getCopyableDirectUrl(video) {
    if (!video || isForumTurboVideo(video)) return '';
    if (isFaphouseVideo(video)) {
        const expiry = String(video.directUrl || '').match(/,(\d{10})\//)?.[1];
        if (expiry && Number(expiry) * 1000 <= Date.now()) return '';
        return video.faphouseResolverVersion === 2 && video.faphouseResolvedUrl === video.directUrl
            ? String(video.directUrl || '') : '';
    }

    // Prednostne vrátime directUrl ak ho už máme (napr. z Erome)
    const direct = String(video.directUrl || '').trim();
    if (isFilesterVideo(video)) return isFilesterPlaybackUrl(direct) ? direct : '';
    if (isPimpBunnyUrl(video.source_url || video.url) && direct && !isSignedPimpBunnyDirectUrl(direct)) return '';
    if (direct) return direct;

    const raw = String(video.url || '').trim();
    if (!raw) return '';
    if (looksLikeDirectMediaUrl(raw)) return raw;
    if (/pixeldrain\.com\/api\/(?:file|filesystem)\//i.test(raw)) return raw;
    if (/gofile\.io\/.*\/download\//i.test(raw) || /store\d+\.gofile\.io\//i.test(raw)) return raw;
    return '';
}

function isBeegVideo(video) {
    if (!video) return false;
    const src = String(video.source_url || video.url || '').toLowerCase();
    return src.includes('beeg.com');
}

function isDetailMetadataSupportedVideo(video) {
    if (!video) return false;
    // Povolíme všetko, čo má aspoň nejakú URL, aby sme sa pokúsili doplniť meta dáta
    return !!(video.source_url || video.url || video.directUrl);
}

// Shared weak-metadata check for supported detail-page sites
function hasWeakDetailMetadata(video) {
    if (!video) return false;
    if (!isDetailMetadataSupportedVideo(video)) return false;
    if (isFaphouseVideo(video)) return !getCopyableDirectUrl(video);
    if (video._metaChecked) return false;
    const q = String(video.quality || '').toLowerCase();
    const weakQ = !q || /^\d+$/.test(q) || q === '720p' || q === 'hd' || q === 'hd?' || q === '?';
    const weakSize = !getVideoSizeBytes(video);
    const weakDuration = !Number(video.duration || 0);
    const thumb = String(video.thumbnail || '').trim();
    const weakThumbnail = !thumb || thumb === 'MISSING_THUMBNAIL';
    return weakQ || weakSize || weakDuration || weakThumbnail;
}

function hasMissingQualityOrSize(video) {
    if (!video || !isDetailMetadataSupportedVideo(video)) return false;
    const q = normalizeQualityLabel(video.quality || qualityLabelFromHeight(Number(video.height || 0)), { allowUnknown: true });
    const missingQuality = !q || q === '?' || q === 'HD?' || /^\d+$/.test(String(video.quality || '').trim());
    const missingSize = getVideoSizeBytes(video) <= 0;
    return missingQuality || missingSize;
}

function isLikelyShortPreview(video) {
    if (!video) return false;
    const duration = Number(video.duration || 0);
    const sizeBytes = Number(getVideoSizeBytes(video) || 0);
    const host = String(getVideoHost(video) || '').toLowerCase();
    const source = String(video.source_url || video.url || '').toLowerCase();
    const isTiny = duration > 0 && duration < 60 && sizeBytes > 0 && sizeBytes < (10 * 1024 * 1024);
    const suspiciousHost = /(?:trafficdeposit|tnmr\.org|sxyprn\.(?:com|net)|playmogo\.com)/i.test(`${host} ${source}`);
    return isTiny || (duration > 0 && duration < 25 && suspiciousHost);
}

function isSuspiciousDirectUrl(url, knownSizeBytes = 0) {
    const raw = String(url || '').trim().toLowerCase();
    if (!raw) return true;
    const size = Number(knownSizeBytes || 0) || 0;
    if (size > 0 && size < (10 * 1024 * 1024)) return true;
    if (/sxyprn\.(?:com|net)\//i.test(raw)) return true;
    if (/tnmr\.org\/hls2\//i.test(raw)) return true;
    if (/trafficdeposit\.com\/.*vidthumb\.mp4/i.test(raw)) return true;
    if (/preview|thumb|small\.mp4|get_preview|vidthumb|trailer|sample|intro/i.test(raw)) return true;
    if (/\.(?:vid)(?:[?#]|$)/i.test(raw) && size < (20 * 1024 * 1024)) return true;
    return false;
}

function isProbablyNonVideoAsset(video) {
    if (!video) return false;
    const blob = `${String(video.url || '')} ${String(video.source_url || '')} ${String(video.title || '')}`.toLowerCase();
    return /\.(?:rar|zip|7z|tar|gz|bz2|iso|dmg|exe|apk|pdf|txt|nfo|srt|ass|vtt)(?:[?#]|$)/i.test(blob);
}

function getMetadataTargetVideos() {
    const folderName = String(document.getElementById('folder-name')?.textContent || '').toLowerCase();
    const isSxyContext = folderName.includes('sxyprn');
    if (isSxyContext) {
        const scope = (Array.isArray(currentlyFilteredVideos) && currentlyFilteredVideos.length > 0)
            ? currentlyFilteredVideos
            : allVideos;
        return scope.filter(v => hasWeakDetailMetadata(v) && !isLikelyShortPreview(v) && !isProbablyNonVideoAsset(v));
    }

    const filtered = Array.isArray(currentlyFilteredVideos) ? currentlyFilteredVideos : [];
    const selectedFiltered = filtered.filter(v => selectedVideos.has(v.id));

    if (selectedFiltered.length > 0) {
        return selectedFiltered.filter(v => hasWeakDetailMetadata(v) && !isLikelyShortPreview(v) && !isProbablyNonVideoAsset(v));
    }

    const weakFiltered = filtered.filter(v => hasWeakDetailMetadata(v) && !isLikelyShortPreview(v) && !isProbablyNonVideoAsset(v));
    if (weakFiltered.length > 0) {
        return weakFiltered;
    }

    return allVideos.filter(v => hasWeakDetailMetadata(v) && !isLikelyShortPreview(v) && !isProbablyNonVideoAsset(v));
}

// Kept for compat
function hasWeakHornySimpMetadata(video) {
    return hasWeakDetailMetadata(video);
}

