// ── PORNDH4K.NET ───────────────────────────────────────────────────────────
async function handlePornHD4KScraping(tab) {
    console.log('PornHD4K scraping:', tab.id, tab.url);
    document.getElementById('loader').style.display = 'flex';
    document.getElementById('video-grid').style.display = 'none';

    const pageLimit = getRequestedPageLimit();
    const autoSend = document.getElementById('send-to-dashboard')?.checked || false;
    const isTurbo = document.getElementById('turbo-mode')?.checked || false;

    try {
        const [{ result }] = await chrome.scripting.executeScript({
            target: { tabId: tab.id },
            func: async (limit) => {
                const absolute = (href, base) => {
                    if (!href) return '';
                    try { return new URL(href, base).href; } catch { return href; }
                };

                function extractFromDoc(doc, baseUrl) {
                    const out = [];
                    const seen = new Set();
                    doc.querySelectorAll('a[href*="/video/"]').forEach(a => {
                        const href = absolute(a.getAttribute('href'), baseUrl);
                        if (seen.has(href)) return;
                        seen.add(href);

                        const card = a.closest('.video-item, .item, article') || a.parentElement;
                        const title = (a.getAttribute('title') || a.textContent || '').trim();
                        if (!title || title.length < 5) return;

                        const img = card.querySelector('img');
                        let thumb = img ? (img.getAttribute('data-src') || img.src || '') : '';
                        if (thumb.startsWith('//')) thumb = 'https:' + thumb;

                        const durText = card.querySelector('.duration, .time')?.textContent || '';

                        out.push({
                            id: href,
                            title: title,
                            url: href,
                            source_url: href,
                            thumbnail: absolute(thumb, baseUrl),
                            duration: durText.trim(),
                            quality: '4K',
                            size: 0
                        });
                    });
                    return out;
                }

                let results = extractFromDoc(document, location.href);

                if (limit > 1) {
                    const current = new URL(location.href);
                    const pageUrls = [];
                    for (let p = 2; p <= limit; p++) {
                        const u = new URL(location.href);
                        u.searchParams.set('page', p);
                        pageUrls.push(u.href);
                    }

                    for (const url of pageUrls) {
                        try {
                            const r = await fetch(url);
                            if (!r.ok) break;
                            const html = await r.text();
                            const d = new DOMParser().parseFromString(html, 'text/html');
                            results = results.concat(extractFromDoc(d, url));
                        } catch { break; }
                    }
                }
                return results;
            },
            args: [pageLimit]
        });

        allVideos = (result || []).map(v => ({
            ...v,
            duration: parseDuration(v.duration)
        }));
        currentlyFilteredVideos = [...allVideos];

        document.getElementById('folder-name').innerText = `PornHD4K${isTurbo ? ' (Turbo)' : ''}`;
        applyFilters();
        updateStats();

        if (autoSend && allVideos.length > 0) {
            importVideos(allVideos, `PornHD4K ${new Date().toLocaleDateString()}`);
        }
    } catch (err) {
        console.error('handlePornHD4KScraping', err);
        showError('PornHD4K: ' + err.message);
    }
}

// ── KATESTUBE.COM ──────────────────────────────────────────────────────────
async function handleKateTubeScraping(tab) {
    console.log('KateTube scraping:', tab.id, tab.url);
    document.getElementById('loader').style.display = 'flex';
    document.getElementById('video-grid').style.display = 'none';

    const pageLimit = getRequestedPageLimit();
    const autoSend = document.getElementById('send-to-dashboard')?.checked || false;
    const isTurbo = document.getElementById('turbo-mode')?.checked || false;

    try {
        const [{ result }] = await chrome.scripting.executeScript({
            target: { tabId: tab.id },
            func: async (limit) => {
                const absolute = (href, base) => {
                    if (!href) return '';
                    try { return new URL(href, base).href; } catch { return href; }
                };

                const cleanText = (value) => String(value || '').replace(/\s+/g, ' ').trim();

                const parseCurrentPage = (value) => {
                    try {
                        const u = new URL(value, location.href);
                        const q = parseInt(u.searchParams.get('page') || u.searchParams.get('p') || '1', 10);
                        if (Number.isFinite(q) && q > 0) return q;
                        const parts = u.pathname.replace(/\/+$/, '').split('/').filter(Boolean);
                        const tail = parseInt(parts[parts.length - 1] || '1', 10);
                        return Number.isFinite(tail) && tail > 0 ? tail : 1;
                    } catch {
                        return 1;
                    }
                };

                const pickThumb = (el, base) => {
                    if (!el) return '';
                    const source = el.querySelector('img[data-src], img[src], img[data-original], video[poster], source[srcset], source[src]');
                    if (!source) return '';
                    let raw = '';
                    if (source.tagName === 'VIDEO') {
                        raw = source.getAttribute('poster') || '';
                    } else if (source.tagName === 'SOURCE') {
                        raw = source.getAttribute('srcset') || source.getAttribute('src') || '';
                        if (raw.includes(',')) raw = raw.split(',')[0].trim().split(' ')[0];
                    } else {
                        raw = source.getAttribute('data-src') || source.getAttribute('data-original') || source.getAttribute('src') || '';
                    }
                    if (raw.startsWith('//')) raw = `https:${raw}`;
                    return absolute(raw, base);
                };

                const pickDuration = (el, fallback = '') => {
                    const pool = [];
                    if (el) {
                        pool.push(el.querySelector('.duration, .time, .video-duration, .thumb-time, .item__duration')?.textContent || '');
                        pool.push(el.getAttribute?.('data-duration') || '');
                        pool.push(el.textContent || '');
                    }
                    pool.push(fallback || '');
                    for (const candidate of pool) {
                        const match = String(candidate || '').match(/\b\d{1,2}:\d{2}(?::\d{2})?\b/);
                        if (match) return match[0];
                    }
                    return '';
                };

                const pickQuality = (el, fallback = '') => {
                    const pool = [];
                    if (el) {
                        pool.push(el.querySelector('.quality, .video-quality, [class*="quality"], [class*="hd"]')?.textContent || '');
                        pool.push(el.getAttribute?.('data-quality') || '');
                        pool.push(el.textContent || '');
                    }
                    pool.push(fallback || '');
                    for (const candidate of pool) {
                        const match = String(candidate || '').match(/\b(?:2160|1440|1080|720|480|360|240)p\b/i);
                        if (match) return match[0].toUpperCase();
                    }
                    return '';
                };

                const blockedVideoHref = (href) => /\/(?:categories?|tags?|pornstars?|profiles?|users?|members?|community|upload|login|new_login|sign(?:-?in|-?up)?|join|register)\b/i.test(href);
                const blockedPageHref = (href) => /\/(?:categories?|tags?|pornstars?|profiles?|users?|members?|community|upload|login|new_login|sign(?:-?in|-?up)?|join|register)\b/i.test(href);

                const isLikelyVideoHref = (href, anchor, card, title) => {
                    const abs = absolute(href, location.href);
                    if (!abs) return false;
                    try {
                        const u = new URL(abs);
                        const host = u.hostname.replace(/^www\./i, '').toLowerCase();
                        if (!host.endsWith('katestube.com')) return false;
                        const low = `${u.pathname}${u.search}`.toLowerCase();
                        if (blockedVideoHref(low)) return false;
                        if (low === '/' || low === '/en' || low === '/videos' || low === '/categories' || low === '/pornstars' || /^\/search\/?$/.test(u.pathname)) return false;
                        if (/\/(?:video|videos|watch)\b/i.test(low)) return true;
                        const cardText = cleanText(card?.textContent || '');
                        const hasThumb = !!pickThumb(card || anchor, location.href);
                        const hasDuration = /\b\d{1,2}:\d{2}(?::\d{2})?\b/.test(cardText);
                        const hasTitle = cleanText(title).length >= 4;
                        const hrefLooksContent = /\/[a-z0-9_-]{6,}/i.test(u.pathname) || /(?:-|_)/.test(u.pathname);
                        return hasTitle && (hasThumb || hasDuration || hrefLooksContent);
                    } catch {
                        return false;
                    }
                };

                const seenVideoUrls = new Set();
                const collectFromDoc = (doc, baseUrl) => {
                    const out = [];
                    const anchors = Array.from(doc.querySelectorAll(
                        'a.ponn[href*="/videos/"], .thumb > a[href*="/videos/"], .thumb a[href*="/videos/"], .item a[href*="/videos/"], [itemprop="url"][href*="/videos/"]'
                    ));
                    for (const a of anchors) {
                        const href = absolute(a.getAttribute('href'), baseUrl);
                        if (!href || seenVideoUrls.has(href)) continue;
                        const card = a.closest('article, li, .item, .thumb, .video-item, .content, .list-video, .thumb-block, .content-item, [class*="thumb"], [class*="video"], [class*="item"]') || a.parentElement;
                        let rawTitle = cleanText(
                            a.getAttribute('title')
                            || a.getAttribute('aria-label')
                            || a.getAttribute('data-title')
                            || a.querySelector('img')?.getAttribute('alt')
                            || a.querySelector('.title, .name, .video-title')?.textContent
                            || a.textContent
                        );
                        if (!rawTitle) rawTitle = cleanText(
                            card?.querySelector('.title, .name, .video-title, h2, h3, h4, strong')?.textContent
                            || card?.querySelector('img')?.getAttribute('alt')
                            || ''
                        );
                        const duration = pickDuration(card, rawTitle);
                        const title = cleanText(
                            rawTitle
                                .replace(/^new\s+\d{1,2}:\d{2}(?::\d{2})?\s+/i, '')
                                .replace(/^\d{1,2}:\d{2}(?::\d{2})?\s+/, '')
                        );
                        if (!isLikelyVideoHref(href, a, card, title)) continue;
                        if (!title || title.length < 4) continue;
                        seenVideoUrls.add(href);
                        out.push({
                            id: href,
                            title,
                            url: href,
                            source_url: href,
                            thumbnail: pickThumb(card || a, baseUrl),
                            duration,
                            quality: pickQuality(card, rawTitle),
                            size: 0,
                        });
                    }
                    return out;
                };

                const collectSingleVideoFallback = (doc, pageUrl) => {
                    const ogTitle = cleanText(doc.querySelector('meta[property="og:title"]')?.getAttribute('content') || '');
                    const titleTag = cleanText(doc.querySelector('title')?.textContent || '');
                    const title = ogTitle || titleTag.replace(/\s*[-|].*$/, '').trim();
                    if (!title) return [];
                    return [{
                        id: pageUrl,
                        title,
                        url: pageUrl,
                        source_url: pageUrl,
                        thumbnail: absolute(
                            doc.querySelector('meta[property="og:image"]')?.getAttribute('content')
                            || doc.querySelector('video[poster]')?.getAttribute('poster')
                            || '',
                            pageUrl
                        ),
                        duration: cleanText(
                            doc.querySelector('meta[property="video:duration"]')?.getAttribute('content')
                            || doc.querySelector('meta[itemprop="duration"]')?.getAttribute('content')
                            || doc.querySelector('.duration, .time, .video-duration')?.textContent
                            || ''
                        ),
                        quality: pickQuality(doc),
                        size: 0,
                    }];
                };

                const findNextPageUrl = (doc, currentUrl) => {
                    const currentPage = parseCurrentPage(currentUrl);
                    const candidates = [];
                    const push = (href) => {
                        const abs = absolute(href, currentUrl);
                        if (!abs || abs === currentUrl) return;
                        try {
                            const u = new URL(abs);
                            if (!u.hostname.replace(/^www\./i, '').toLowerCase().endsWith('katestube.com')) return;
                            if (blockedPageHref(`${u.pathname}${u.search}`.toLowerCase())) return;
                            candidates.push(abs);
                        } catch { }
                    };

                    push(doc.querySelector('link[rel="next"]')?.getAttribute('href'));
                    push(doc.querySelector('a[rel="next"], a.next, .pagination a.next, .pager a.next')?.getAttribute('href'));
                    Array.from(doc.querySelectorAll('a[href]')).forEach((a) => {
                        const text = cleanText(a.textContent).toLowerCase();
                        const aria = cleanText(a.getAttribute('aria-label') || '').toLowerCase();
                        if (text === 'next' || text === '>' || aria.includes('next')) push(a.getAttribute('href'));
                        const pageNum = parseInt(text, 10);
                        if (Number.isFinite(pageNum) && pageNum === currentPage + 1) push(a.getAttribute('href'));
                    });

                    return candidates.find(Boolean) || '';
                };

                let pageUrl = location.href;
                let doc = document;
                let pageIndex = 0;
                let results = [];
                const visitedPages = new Set();

                while (doc && pageUrl && pageIndex < Math.max(1, Number(limit || 1))) {
                    if (visitedPages.has(pageUrl)) break;
                    visitedPages.add(pageUrl);
                    pageIndex += 1;

                    const pageItems = collectFromDoc(doc, pageUrl);
                    if (pageItems.length > 0) {
                        results = results.concat(pageItems);
                    } else if (pageIndex === 1) {
                        results = results.concat(collectSingleVideoFallback(doc, pageUrl));
                    }

                    if (pageIndex >= Math.max(1, Number(limit || 1))) break;
                    const nextUrl = findNextPageUrl(doc, pageUrl);
                    if (!nextUrl || visitedPages.has(nextUrl)) break;

                    try {
                        const resp = await fetch(nextUrl, { credentials: 'include' });
                        if (!resp.ok) break;
                        const html = await resp.text();
                        doc = new DOMParser().parseFromString(html, 'text/html');
                        pageUrl = nextUrl;
                    } catch {
                        break;
                    }
                }

                return results;
            },
            args: [pageLimit],
        });

        allVideos = (result || []).map(v => ({
            ...v,
            duration: parseDuration(v.duration)
        }));
        currentlyFilteredVideos = [...allVideos];

        document.getElementById('folder-name').innerText = `KateTube${isTurbo ? ' (Turbo)' : ''}`;
        applyFilters();
        updateStats();

        if (autoSend && allVideos.length > 0) {
            importVideos(allVideos, `KateTube ${new Date().toLocaleDateString()}`);
        }
    } catch (err) {
        console.error('handleKateTubeScraping', err);
        showError('KateTube: ' + err.message);
    }
}


// ── BIGPORN.COM ───────────────────────────────────────────────────────────────
async function handleBigpornScraping(tab) {
    console.log('BigPorn scraping:', tab.id, tab.url);
    document.getElementById('loader').style.display = 'flex';
    document.getElementById('video-grid').style.display = 'none';

    const pageLimit = getRequestedPageLimit();
    const autoSend = document.getElementById('send-to-dashboard')?.checked || false;
    const isTurbo = document.getElementById('turbo-mode')?.checked || false;

    const statsEl = document.getElementById('stats-text');
    if (statsEl) statsEl.innerText = 'BigPorn: načítavam...';

    try {
        const [{ result }] = await chrome.scripting.executeScript({
            target: { tabId: tab.id },
            func: async (limit) => {
                const absolute = (href, base) => {
                    if (!href) return '';
                    try { return new URL(href, base).href; } catch { return href; }
                };

                const cleanText = (v) => String(v || '').replace(/\s+/g, ' ').trim();

                const parseDur = (txt) => {
                    const t = String(txt || '').replace(/[^\d:]/g, '');
                    const parts = t.split(':').filter(s => s !== '');
                    if (!parts.length) return 0;
                    const nums = parts.map(Number);
                    if (nums.length === 3) return nums[0] * 3600 + nums[1] * 60 + nums[2];
                    if (nums.length === 2) return nums[0] * 60 + nums[1];
                    return nums[0] || 0;
                };

                // Resolve next page URL from current listing URL (N.html → N+1.html)
                const nextPageUrl = (currentUrl, page) => {
                    try {
                        const u = new URL(currentUrl);
                        // Pattern: /tag-slug/N.html or /category-slug/N.html etc.
                        u.pathname = u.pathname.replace(/\/(\d+)\.html$/, `/${page}.html`);
                        return u.href;
                    } catch { return null; }
                };

                const extractFromDoc = (doc, baseUrl) => {
                    const out = [];
                    const seen = new Set();

                    doc.querySelectorAll('div.thumb-block-small').forEach(card => {
                        const a = card.querySelector('a[href*=".html"]');
                        if (!a) return;

                        const href = absolute(a.getAttribute('href') || '', baseUrl);
                        if (!href || seen.has(href)) return;

                        // Skip tag/category/site/model listing links (not video watch pages)
                        try {
                            const path = new URL(href).pathname;
                            if (/^\/(tag-|category-|site-|pornstars|search|model)/i.test(path)) return;
                            // Video watch pages: /straight-NNN.html or /gay-NNN.html or /shemale-NNN.html
                            if (!/\/(straight|gay|shemale|lesbian|bisexual|trans)-\d+\.html/i.test(path)) return;
                        } catch { return; }

                        seen.add(href);

                        const title = cleanText(
                            a.getAttribute('title') ||
                            card.querySelector('p:not(.tags)')?.textContent ||
                            a.textContent
                        );
                        if (!title || title.length < 3) return;

                        const img = card.querySelector('img');
                        let thumb = img ? (
                            img.getAttribute('data-src') ||
                            img.getAttribute('src') || ''
                        ) : '';
                        if (thumb.startsWith('//')) thumb = 'https:' + thumb;

                        const durEl = card.querySelector('.time-small, .duration, .time');
                        const duration = parseDur(durEl?.textContent || '');

                        // Tags from the card
                        const tagLinks = Array.from(card.querySelectorAll('p.tags a'));
                        const tags = tagLinks.map(t => cleanText(t.textContent)).filter(Boolean);

                        out.push({
                            id: href,
                            url: href,
                            source_url: href,
                            title,
                            thumbnail: absolute(thumb, baseUrl),
                            duration,
                            quality: 'HD',
                            size: 0,
                            tags,
                        });
                    });
                    return out;
                };

                let results = extractFromDoc(document, location.href);

                if (limit > 1) {
                    // Determine current page number from URL (e.g. /tag-xxx/1.html → 1)
                    const curMatch = location.pathname.match(/\/(\d+)\.html$/);
                    const curPage = curMatch ? parseInt(curMatch[1], 10) : 1;

                    for (let p = curPage + 1; p <= curPage + limit - 1; p++) {
                        const url = nextPageUrl(location.href, p);
                        if (!url) break;
                        try {
                            const r = await fetch(url, { credentials: 'include' });
                            if (!r.ok) break;
                            const html = await r.text();
                            const doc = new DOMParser().parseFromString(html, 'text/html');
                            const batch = extractFromDoc(doc, url);
                            if (!batch.length) break;
                            results = results.concat(batch);
                        } catch { break; }
                    }
                }

                // Dedupe
                const seen2 = new Set();
                return results.filter(v => { if (seen2.has(v.url)) return false; seen2.add(v.url); return true; });
            },
            args: [pageLimit],
        });

        allVideos = (result || [])
            .filter(v => v?.url && v?.title)
            .map(v => ({
                id: v.id || v.url,
                url: v.url,
                source_url: v.source_url || v.url,
                title: String(v.title || 'BigPorn Video').trim(),
                thumbnail: String(v.thumbnail || '').trim(),
                duration: typeof v.duration === 'number' ? v.duration : parseDuration(String(v.duration || '')),
                quality: 'HD',
                size: 0,
                tags: Array.isArray(v.tags) ? v.tags : [],
            }));
        currentlyFilteredVideos = [...allVideos];

        const folderEl = document.getElementById('folder-name');
        if (folderEl) {
            if (folderEl.firstChild) folderEl.firstChild.textContent = `BigPorn${isTurbo ? ' (Turbo)' : ''} `;
            else folderEl.textContent = `BigPorn${isTurbo ? ' (Turbo)' : ''}`;
        }
        applyFilters();
        updateStats();

        if (autoSend && allVideos.length > 0) {
            importVideos(allVideos, `BigPorn ${new Date().toLocaleDateString()}`);
        }
    } catch (err) {
        console.error('handleBigpornScraping', err);
        showError('BigPorn: ' + err.message);
    }
}

// ── IXXX.COM ──────────────────────────────────────────────────────────────────
// iXXX is an aggregator — each card links to /out/?l=<msgpack+base64> which
// encodes the real external URL (xvideos, pornzona, zbgalleries, etc.).
// We decode the l= param in-page (atob + byte scan) to get the actual URL.
async function handleIxxxScraping(tab) {
    console.log('iXXX scraping:', tab.id, tab.url);
    document.getElementById('loader').style.display = 'flex';
    document.getElementById('video-grid').style.display = 'none';

    const pageLimit = getRequestedPageLimit();
    const autoSend = document.getElementById('send-to-dashboard')?.checked || false;
    const isTurbo = document.getElementById('turbo-mode')?.checked || false;

    const statsEl = document.getElementById('stats-text');
    if (statsEl) statsEl.innerText = 'iXXX: načítavam...';

    try {
        const [{ result }] = await chrome.scripting.executeScript({
            target: { tabId: tab.id },
            func: async (limit) => {
                const cleanText = (v) => String(v || '').replace(/\s+/g, ' ').trim();

                // Decode the /out/?l= param — msgpack binary, URL is a plain https:// substring
                const decodeOutUrl = (href) => {
                    try {
                        const l = new URL(href, location.href).searchParams.get('l');
                        if (!l) return null;
                        // atob needs standard base64; the param uses url-safe chars occasionally
                        const b64 = l.replace(/-/g, '+').replace(/_/g, '/');
                        const bin = atob(b64);
                        // Scan binary for https:// sequence
                        const marker = 'https://';
                        const idx = bin.indexOf(marker);
                        if (idx === -1) return null;
                        // Read until first control char or space
                        let end = idx;
                        while (end < bin.length && bin.charCodeAt(end) > 0x1f && bin.charCodeAt(end) < 0x7f && bin[end] !== '"' && bin[end] !== "'") end++;
                        return bin.slice(idx, end) || null;
                    } catch { return null; }
                };

                const extractFromDoc = (doc) => {
                    const out = [];
                    const seen = new Set();

                    // Each video card: <div class="card sub ..."> containing <a class="item-link" href="/out/?l=...">
                    doc.querySelectorAll('a[href^="/out/"]').forEach(a => {
                        const rawHref = a.getAttribute('href') || '';
                        // Only take item-link anchors (thumbnail links), not site-source links
                        if (!a.classList.contains('item-link') && !a.closest('[data-public-id]')) return;

                        const externalUrl = decodeOutUrl(rawHref);
                        if (!externalUrl || seen.has(externalUrl)) return;
                        seen.add(externalUrl);

                        const card = a.closest('[data-public-id]') || a.parentElement;

                        // Title from img alt or link title attr
                        const img = a.querySelector('img.item-image') || a.querySelector('img');
                        const title = cleanText(
                            a.getAttribute('title') ||
                            img?.getAttribute('alt') || ''
                        );
                        if (!title || title.length < 3) return;

                        const thumb = img?.getAttribute('src') || '';

                        // Duration — look for time element in card
                        const durEl = card?.querySelector('[class*="duration"], [class*="time"], time');
                        const durText = cleanText(durEl?.textContent || '');
                        let duration = 0;
                        const dm = durText.match(/(\d+):(\d{2})/);
                        if (dm) duration = parseInt(dm[1]) * 60 + parseInt(dm[2]);

                        // Quality hint from filter/search context or card badge
                        const qualEl = card?.querySelector('[class*="quality"], [class*="hd"], [class*="4k"]');
                        const quality = cleanText(qualEl?.textContent || 'HD') || 'HD';

                        out.push({ url: externalUrl, source_url: externalUrl, title, thumbnail: thumb, duration, quality, size: 0, tags: [] });
                    });
                    return out;
                };

                let results = extractFromDoc(document);

                // Multi-page: iXXX uses ?page=N
                if (limit > 1) {
                    for (let p = 2; p <= limit; p++) {
                        try {
                            const u = new URL(location.href);
                            u.searchParams.set('page', p);
                            const r = await fetch(u.href, { credentials: 'include' });
                            if (!r.ok) break;
                            const html = await r.text();
                            const doc = new DOMParser().parseFromString(html, 'text/html');
                            const batch = extractFromDoc(doc);
                            if (!batch.length) break;
                            results = results.concat(batch);
                        } catch { break; }
                    }
                }

                // Dedupe by external URL
                const seen2 = new Set();
                return results.filter(v => { if (seen2.has(v.url)) return false; seen2.add(v.url); return true; });
            },
            args: [pageLimit],
        });

        allVideos = (result || [])
            .filter(v => v?.url && v?.title)
            .map(v => ({
                id: v.url,
                url: v.url,
                source_url: v.source_url || v.url,
                title: String(v.title).trim(),
                thumbnail: String(v.thumbnail || '').trim(),
                duration: typeof v.duration === 'number' ? v.duration : parseDuration(String(v.duration || '')),
                quality: String(v.quality || 'HD').trim(),
                size: 0,
                tags: [],
            }));
        currentlyFilteredVideos = [...allVideos];

        const folderEl = document.getElementById('folder-name');
        if (folderEl) {
            if (folderEl.firstChild) folderEl.firstChild.textContent = `iXXX${isTurbo ? ' (Turbo)' : ''} `;
            else folderEl.textContent = `iXXX${isTurbo ? ' (Turbo)' : ''}`;
        }
        applyFilters();
        updateStats();

        if (autoSend && allVideos.length > 0) {
            importVideos(allVideos, `iXXX ${new Date().toLocaleDateString()}`);
        }
    } catch (err) {
        console.error('handleIxxxScraping', err);
        showError('iXXX: ' + err.message);
    }
}

// ── FUQ.COM ───────────────────────────────────────────────────────────────────
// fuq.com is an aggregator — video cards link to /out/?l=<base64/msgpack>
// which encodes the real external URL. Same system as iXXX.com.
async function handleFuqScraping(tab) {
    console.log('Fuq scraping:', tab.id, tab.url);
    document.getElementById('loader').style.display = 'flex';
    document.getElementById('video-grid').style.display = 'none';

    const pageLimit = getRequestedPageLimit();
    const autoSend = document.getElementById('send-to-dashboard')?.checked || false;
    const isTurbo = document.getElementById('turbo-mode')?.checked || false;

    const statsEl = document.getElementById('stats-text');
    if (statsEl) statsEl.innerText = 'Fuq: načítavam...';

    try {
        const [{ result }] = await chrome.scripting.executeScript({
            target: { tabId: tab.id },
            func: async (limit) => {
                const cleanText = (v) => String(v || '').replace(/\s+/g, ' ').trim();

                // Decode /out/?l= param — same msgpack/base64 as iXXX.com
                // The binary blob contains a plain https:// URL as a substring
                const decodeOutUrl = (href) => {
                    try {
                        const l = new URL(href, location.href).searchParams.get('l');
                        if (!l) return null;
                        const b64 = l.replace(/-/g, '+').replace(/_/g, '/');
                        const bin = atob(b64);
                        const marker = 'https://';
                        const idx = bin.indexOf(marker);
                        if (idx === -1) return null;
                        let end = idx;
                        while (end < bin.length && bin.charCodeAt(end) > 0x1f && bin.charCodeAt(end) < 0x80 && bin[end] !== '"' && bin[end] !== "'" && bin[end] !== ' ') end++;
                        const url = bin.slice(idx, end).trim();
                        return url.startsWith('https://') ? url : null;
                    } catch { return null; }
                };

                const qualityH = (text) => {
                    const t = String(text || '');
                    if (/\b4[Kk]\b/.test(t)) return 2160;
                    return parseInt(t.match(/(2160|1440|1080|720|480|360|240)p?/i)?.[1] || '0', 10) || 0;
                };

                // fuq.com pagination: ?page=N  (query param, like iXXX)
                const nextPageUrl = (currentUrl, pageNum) => {
                    try {
                        const u = new URL(currentUrl);
                        u.searchParams.set('page', pageNum);
                        return u.href;
                    } catch { return null; }
                };

                const extractFromDoc = (doc) => {
                    const out = [];
                    const seen = new Set();

                    // All /out/ links that contain an img (thumbnail anchors)
                    doc.querySelectorAll('a[href^="/out/"]').forEach(a => {
                        const rawHref = a.getAttribute('href') || '';
                        if (!a.querySelector('img') && !a.closest('figure, li, article')?.querySelector('img')) return;

                        const externalUrl = decodeOutUrl(rawHref);
                        if (!externalUrl || seen.has(externalUrl)) return;
                        seen.add(externalUrl);

                        const card = a.closest('figure, li, article, div') || a;
                        const img = a.querySelector('img') || card.querySelector('img');

                        let thumb = img ? (img.getAttribute('data-src') || img.getAttribute('data-original') || img.getAttribute('src') || '') : '';
                        if (thumb.startsWith('//')) thumb = 'https:' + thumb;

                        // Duration — scan text nodes for MM:SS pattern
                        let duration = 0;
                        const walker = document.createTreeWalker(card, NodeFilter.SHOW_TEXT);
                        let tn;
                        while ((tn = walker.nextNode())) {
                            const t = tn.textContent.trim();
                            if (/^\d{1,2}:\d{2}(:\d{2})?$/.test(t)) {
                                const parts = t.split(':').map(Number);
                                duration = parts.length === 3 ? parts[0] * 3600 + parts[1] * 60 + parts[2] : parts[0] * 60 + parts[1];
                                break;
                            }
                        }

                        // Quality badge text anywhere in card
                        const cardText = card.innerText || card.textContent || '';
                        const qm = cardText.match(/\b(4K|2160p|1440p|1080p|720p|480p|360p|HD)\b/i);
                        const height = qualityH(qm ? qm[1] : '');

                        const title = cleanText(
                            a.getAttribute('title') ||
                            img?.getAttribute('alt') ||
                            card.querySelector('.title, .name, h3, h2, p')?.textContent ||
                            a.textContent
                        ) || 'Fuq Video';
                        if (title.length < 2) return;

                        out.push({
                            id: externalUrl,
                            url: externalUrl,
                            source_url: externalUrl,
                            title,
                            thumbnail: thumb,
                            duration,
                            height,
                            quality: height >= 2160 ? '4K (2160p)' : (height > 0 ? `${height}p` : 'HD'),
                            size: 0,
                            tags: [],
                        });
                    });
                    return out;
                };

                let results = extractFromDoc(document);

                // Multi-page via ?page=N
                if (limit > 1) {
                    for (let p = 2; p <= limit; p++) {
                        const url = nextPageUrl(location.href, p);
                        if (!url) break;
                        try {
                            const r = await fetch(url, { credentials: 'include' });
                            if (!r.ok) break;
                            const html = await r.text();
                            const doc = new DOMParser().parseFromString(html, 'text/html');
                            const batch = extractFromDoc(doc);
                            if (!batch.length) break;
                            results = results.concat(batch);
                            await chrome.runtime.sendMessage({ action: 'NEXUS_SCAN_PROGRESS', source: 'Fuq', page: p, found: results.length });
                        } catch { break; }
                    }
                }

                const seen2 = new Set();
                return results.filter(v => { if (seen2.has(v.url)) return false; seen2.add(v.url); return true; });
            },
            args: [isTurbo ? 4 : pageLimit],
        });

        allVideos = (result || [])
            .filter(v => v?.url && v?.title)
            .map(v => ({
                id: v.id || v.url,
                url: v.url,
                source_url: v.source_url || v.url,
                title: String(v.title || 'Fuq Video').trim(),
                thumbnail: String(v.thumbnail || '').trim(),
                duration: typeof v.duration === 'number' ? v.duration : parseDuration(String(v.duration || '')),
                height: Number(v.height || 0) || 0,
                quality: String(v.quality || 'HD').trim(),
                size: 0,
                tags: Array.isArray(v.tags) ? v.tags : [],
            }));
        currentlyFilteredVideos = [...allVideos];

        const folderEl = document.getElementById('folder-name');
        if (folderEl) {
            if (folderEl.firstChild) folderEl.firstChild.textContent = `Fuq${isTurbo ? ' (Turbo)' : ''} `;
            else folderEl.textContent = `Fuq${isTurbo ? ' (Turbo)' : ''}`;
        }
        applyFilters();
        updateStats();

        if (autoSend && allVideos.length > 0) {
            importVideos(allVideos, `Fuq ${new Date().toLocaleDateString()}`);
        }
    } catch (err) {
        console.error('handleFuqScraping', err);
        showError('Fuq: ' + err.message);
    }
}

async function handlePxpScraping(tab) {
    console.log('PornXP scraping:', tab.id, tab.url);
    document.getElementById('loader').style.display = 'flex';
    document.getElementById('video-grid').style.display = 'none';

    const pageLimit = getRequestedPageLimit();
    const autoSend = document.getElementById('send-to-dashboard')?.checked || false;
    const isTurbo = document.getElementById('turbo-mode')?.checked || false;

    const statsEl = document.getElementById('stats-text');
    if (statsEl) statsEl.innerText = 'PornXP: načítavam...';

    try {
        // Step 1: collect listing cards (title/thumb/duration/tags/url) — cheap, single DOM pass.
        const [{ result }] = await chrome.scripting.executeScript({
            target: { tabId: tab.id },
            func: async (limit) => {
                const cleanText = (v) => String(v || '').replace(/\s+/g, ' ').trim();
                const parseDurationText = (raw) => {
                    const parts = String(raw || '').trim().split(':').map(Number);
                    if (!parts.length || parts.some((n) => !Number.isFinite(n))) return 0;
                    if (parts.length === 2) return parts[0] * 60 + parts[1];
                    if (parts.length === 3) return parts[0] * 3600 + parts[1] * 60 + parts[2];
                    return 0;
                };

                const nextPageUrl = (currentUrl, pageNum) => {
                    try {
                        const u = new URL(currentUrl);
                        const parts = u.pathname.split('/').filter(Boolean);
                        // Listing paths look like /tags/<name> or /tags/<name>/<page> or /best/<page>
                        const lastIsNum = /^\d+$/.test(parts[parts.length - 1] || '');
                        if (lastIsNum) parts[parts.length - 1] = String(pageNum);
                        else parts.push(String(pageNum));
                        u.pathname = `/${parts.join('/')}`;
                        return u.href;
                    } catch { return null; }
                };

                const extractFromDoc = (doc) => {
                    const out = [];
                    const seen = new Set();
                    doc.querySelectorAll('.item_cont').forEach((cont) => {
                        const link = cont.querySelector('a[href*="/videos/"]');
                        if (!link) return;
                        let url = link.getAttribute('href') || '';
                        if (!url) return;
                        try { url = new URL(url, location.origin).href; } catch { return; }
                        if (!/\/videos\/\d+/i.test(url) || seen.has(url)) return;
                        seen.add(url);

                        const img = cont.querySelector('img');
                        let thumbnail = img?.getAttribute('data-src') || img?.getAttribute('src') || '';
                        if (thumbnail && thumbnail.startsWith('/')) thumbnail = new URL(thumbnail, location.origin).href;
                        if (thumbnail.startsWith('//')) thumbnail = `https:${thumbnail}`;

                        const durationLabel = cont.querySelector('.item_dur')?.textContent || '';
                        const title = cleanText(cont.querySelector('.item_title')?.textContent) || 'PornXP Video';
                        const tagLinks = Array.from(cont.parentElement?.querySelectorAll('.item_tags a[href*="/tags/"]') || [])
                            .map((a) => cleanText(a.textContent)).filter(Boolean);

                        out.push({
                            id: url,
                            url,
                            source_url: url,
                            title,
                            thumbnail,
                            duration: parseDurationText(durationLabel),
                            height: 0,
                            quality: '',
                            size: 0,
                            tags: tagLinks,
                        });
                    });
                    return out;
                };

                let results = extractFromDoc(document);

                if (limit > 1) {
                    for (let p = 2; p <= limit; p++) {
                        const url = nextPageUrl(location.href, p);
                        if (!url) break;
                        try {
                            const r = await fetch(url, { credentials: 'include' });
                            if (!r.ok) break;
                            const html = await r.text();
                            const doc = new DOMParser().parseFromString(html, 'text/html');
                            const batch = extractFromDoc(doc);
                            if (!batch.length) break;
                            results = results.concat(batch);
                            await chrome.runtime.sendMessage({ action: 'NEXUS_SCAN_PROGRESS', source: 'PornXP', page: p, found: results.length });
                        } catch { break; }
                    }
                }

                const seen2 = new Set();
                return results.filter((v) => { if (seen2.has(v.url)) return false; seen2.add(v.url); return true; });
            },
            args: [isTurbo ? 4 : pageLimit],
        });

        let scraped = (result || [])
            .filter((v) => v?.url && v?.title)
            .map((v) => ({
                id: v.id || v.url,
                url: v.url,
                source_url: v.source_url || v.url,
                title: String(v.title || 'PornXP Video').trim(),
                thumbnail: String(v.thumbnail || '').trim(),
                duration: typeof v.duration === 'number' ? v.duration : parseDuration(String(v.duration || '')),
                height: Number(v.height || 0) || 0,
                quality: String(v.quality || '').trim(),
                size: 0,
                tags: Array.isArray(v.tags) ? v.tags : [],
            }));

        allVideos = scraped;
        currentlyFilteredVideos = [...allVideos];

        const folderEl = document.getElementById('folder-name');
        if (folderEl) {
            if (folderEl.firstChild) folderEl.firstChild.textContent = `PornXP${isTurbo ? ' (Turbo)' : ''} `;
            else folderEl.textContent = `PornXP${isTurbo ? ' (Turbo)' : ''}`;
        }
        applyFilters();
        updateStats();

        // Step 2: fast-fetch — resolve direct mp4 + quality per video, concurrently in-tab.
        // pxp.cool watch pages expose <source src="..." title="NNNp"> tags directly, so this
        // is cheap (no login gate, no signed-token expiry observed) and worth doing eagerly
        // instead of waiting on the separate "Doplniť meta" / "Direct" buttons.
        if (scraped.length && tab?.id) {
            if (statsEl) statsEl.innerText = `PornXP: fast-fetch 0/${scraped.length}...`;
            const CONCURRENCY = 5;
            let done = 0;
            for (let i = 0; i < scraped.length; i += CONCURRENCY) {
                const chunk = scraped.slice(i, i + CONCURRENCY);
                const urls = chunk.map((v) => v.source_url);
                const [{ result: metaResult }] = await chrome.scripting.executeScript({
                    target: { tabId: tab.id },
                    func: async (pageUrls) => {
                        const out = {};
                        await Promise.all(pageUrls.map(async (pageUrl) => {
                            try {
                                const resp = await fetch(pageUrl, { credentials: 'include' });
                                if (!resp.ok) return;
                                const html = await resp.text();
                                const doc = new DOMParser().parseFromString(html, 'text/html');
                                const sources = [];
                                const re = /<source\s+src="([^"]+)"\s+title="(\d+)p"/gi;
                                let m;
                                while ((m = re.exec(html))) {
                                    let src = m[1];
                                    if (src.startsWith('//')) src = `https:${src}`;
                                    sources.push({ url: src, height: parseInt(m[2], 10) || 0 });
                                }
                                sources.sort((a, b) => b.height - a.height);
                                const best = sources[0] || null;
                                const poster = doc.querySelector('video#player')?.getAttribute('poster') || '';
                                const thumbnail = poster ? new URL(poster, pageUrl).href : '';
                                const tags = Array.from(doc.querySelectorAll('a[href*="/tags/"]')).map((a) => a.textContent.trim()).filter(Boolean);
                                out[pageUrl] = {
                                    directUrl: best?.url || '',
                                    height: best?.height || 0,
                                    thumbnail,
                                    tags: Array.from(new Set(tags)),
                                };
                            } catch { /* leave unresolved */ }
                        }));
                        return out;
                    },
                    args: [urls],
                });

                chunk.forEach((v) => {
                    const meta = metaResult?.[v.source_url];
                    if (!meta) return;
                    const video = allVideos.find((x) => x.id === v.id);
                    if (!video) return;
                    if (meta.directUrl) video.directUrl = meta.directUrl;
                    if (meta.height > 0) { video.height = meta.height; video.quality = `${meta.height}p`; }
                    if (meta.thumbnail && !video.thumbnail) video.thumbnail = meta.thumbnail;
                    if (Array.isArray(meta.tags) && meta.tags.length) video.tags = meta.tags;
                    video._metaChecked = true;
                });

                done += chunk.length;
                if (statsEl) statsEl.innerText = `PornXP: fast-fetch ${Math.min(done, scraped.length)}/${scraped.length}...`;
                applyFilters();
                updateStats();
            }
        }

        if (autoSend && allVideos.length > 0) {
            importVideos(allVideos, `PornXP ${new Date().toLocaleDateString()}`);
        }
    } catch (err) {
        console.error('handlePxpScraping', err);
        showError('PornXP: ' + err.message);
    }
}

function scrapeDrtuberCardsFromPage() {
    const root = document.querySelector('.thumbs_box .thumbs');
    if (!root) return [];

    const parseDuration = (text) => {
        const match = String(text || '').match(/\b(?:(\d{1,2}):)?(\d{1,2}):(\d{2})\b/);
        if (!match) return 0;
        return match[1]
            ? Number(match[1]) * 3600 + Number(match[2]) * 60 + Number(match[3])
            : Number(match[2]) * 60 + Number(match[3]);
    };
    const qualityHeight = (text) => {
        const match = String(text || '').match(/\b(2160|1440|1080|720|480|360|240)p?\b|4k/i);
        return match ? (/^4k$/i.test(match[0]) ? 2160 : Number.parseInt(match[0], 10) || 0) : 0;
    };
    const parseSizeBytes = (text) => {
        const match = String(text || '').match(/\b([\d.,]+)\s*(TB|GB|MB|KB|B)\b/i);
        if (!match) return 0;
        const amount = Number.parseFloat(match[1].replace(',', '.'));
        const unit = match[2].toUpperCase();
        const multiplier = { B: 1, KB: 1024, MB: 1024 ** 2, GB: 1024 ** 3, TB: 1024 ** 4 }[unit];
        return Number.isFinite(amount) ? Math.round(amount * multiplier) : 0;
    };

    return Array.from(root.querySelectorAll(':scope > a.th.ch-video[href*="/video/"]'))
        .map((card) => {
            let pageUrl;
            try {
                pageUrl = new URL(card.getAttribute('href') || card.href, location.href);
            } catch {
                return null;
            }
            if (!/(^|\.)drtuber\.com$/i.test(pageUrl.hostname)) return null;
            const match = pageUrl.pathname.match(/^\/video\/(\d+)(?:\/([^/?#]*))?/i);
            if (!match) return null;

            const image = card.querySelector('img');
            const title = image?.getAttribute('alt')?.trim()
                || card.querySelector('span em')?.textContent?.trim()
                || card.getAttribute('title')?.trim()
                || 'DrTuber video';
            const qualityElements = Array.from(card.querySelectorAll('.quality, .nvs-badge-quality'));
            const qualityText = qualityElements.map((element) =>
                `${element.textContent || ''} ${element.className || ''}`
            ).join(' ');
            const height = qualityHeight(qualityText || card.textContent || '');
            const url = `https://www.drtuber.com/video/${match[1]}${match[2] ? `/${match[2]}` : ''}`;
            const sizeBytes = parseSizeBytes(card.textContent || '');

            return {
                id: match[1],
                url,
                source_url: url,
                title,
                thumbnail: image?.currentSrc || image?.getAttribute('data-src') || image?.getAttribute('src') || '',
                duration: parseDuration(card.querySelector('.time_thumb')?.textContent || card.textContent),
                height,
                quality: height ? (height >= 2160 ? '4K' : `${height}p`) : '',
                size: sizeBytes,
                sizeBytes,
                tags: ['drtuber'],
            };
        })
        .filter((video) => video?.url && video.title);
}

async function handleDrtuberScraping(tab) {
    console.log('DrTuber scraping:', tab.id, tab.url);
    const loader = document.getElementById('loader');
    const videoGrid = document.getElementById('video-grid');
    if (loader) loader.style.display = 'flex';
    if (videoGrid) videoGrid.style.display = 'none';
    const stats = document.getElementById('stats-text');
    if (stats) stats.innerText = 'DrTuber: hľadám videá na stránke...';

    const [{ result }] = await chrome.scripting.executeScript({
        target: { tabId: tab.id },
        func: scrapeDrtuberCardsFromPage,
    });
    const scraped = Array.isArray(result) ? result : [];
    if (!scraped.length) {
        throw new Error('DrTuber: na stránke sa nenašli žiadne video karty.');
    }

    allVideos = scraped.map((video) => normalizeVideoSizeFields(video));
    currentlyFilteredVideos = [...allVideos];
    selectedVideos.clear();
    const folder = document.getElementById('folder-name');
    if (folder?.firstChild) folder.firstChild.textContent = 'DrTuber ';
    applyFilters();
    updateStats();
}

async function handleBase64Scraping(tab) {
    console.log('Fallback Base64 scanning:', tab.id, tab.url);
    document.getElementById('loader').style.display = 'flex';
    document.getElementById('video-grid').style.display = 'none';

    const statsEl = document.getElementById('stats-text');
    if (statsEl) statsEl.innerText = 'Deep Scan: Hľadám Base64 odkazy...';

    try {
        const [{ result }] = await chrome.scripting.executeScript({
            target: { tabId: tab.id },
            func: () => {
                const foundLinks = new Set();
                const textNodes = [];
                const walk = document.createTreeWalker(document.body, NodeFilter.SHOW_TEXT, null, false);
                let n;
                while (n = walk.nextNode()) {
                    textNodes.push(n.nodeValue);
                }
                const fullText = textNodes.join(' ');

                // Base64 usually looks like aHR0c..., length > 20
                // Match base64 strings
                const b64Regex = /(?:[A-Za-z0-9+/]{4}){5,}(?:[A-Za-z0-9+/]{2}==|[A-Za-z0-9+/]{3}=)?/g;
                let match;
                while ((match = b64Regex.exec(fullText)) !== null) {
                    try {
                        const decoded = atob(match[0]);
                        if (decoded.startsWith('http://') || decoded.startsWith('https://')) {
                            // Only keep supported hosts
                            if (/bunkr\.|mega\.nz|filester\.|cyberdrop\.|gofile\./i.test(decoded)) {
                                foundLinks.add(decoded);
                            }
                        }
                    } catch (e) {
                        // ignore invalid base64
                    }
                }

                // Also check hrefs if someone linked a base64 string
                document.querySelectorAll('a').forEach(a => {
                    const text = a.textContent.trim();
                    try {
                        const decoded = atob(text);
                        if ((decoded.startsWith('http://') || decoded.startsWith('https://')) && /bunkr\.|mega\.nz|filester\.|cyberdrop\.|gofile\./i.test(decoded)) {
                            foundLinks.add(decoded);
                        }
                    } catch (e) { }
                });

                return Array.from(foundLinks).map(url => ({
                    id: 'b64-' + Math.random().toString(36).substr(2, 9),
                    url: url,
                    title: "Base64 Objav (" + (new URL(url)).hostname + ")",
                    thumbnail_path: null,
                    duration: 0,
                    sizeBytes: 0,
                    uploadDate: new Date().toISOString()
                }));
            }
        });

        if (result && result.length > 0) {
            const cacheHits = await hydrateFaphouseCardsFromCache(result);
            allVideos = result;
            currentlyFilteredVideos = [...allVideos];
            document.getElementById('turbo-controls').style.display = 'flex';
        } else {
            const container = document.querySelector('.container');
            if (container) container.innerHTML = '<div style="padding:40px;text-align:center;opacity:0.6;"><h3>Žiadne kompatibilné Base64 odkazy</h3><p>Tento web nie je priamo podporovaný a nenašli sa ani skryté odkazy na Bunkr/Mega/Filester.</p></div>';
        }
    } catch (e) {
        console.error("Base64 scan error", e);
    }
}

async function handleBaddiehubScraping(tab) {
    console.log('Baddiehub scraping:', tab.id, tab.url);
    document.getElementById('loader').style.display = 'flex';
    document.getElementById('video-grid').style.display = 'none';

    try {
        const [{ result }] = await chrome.scripting.executeScript({
            target: { tabId: tab.id },
            func: async () => {
                const results = [];
                const links = document.querySelectorAll('a[href]');
                const foundUrls = new Set();

                for (const a of links) {
                    try {
                        const href = a.href;
                        const url = new URL(href);

                        if (url.hostname.includes('baddiehub.com')) {
                            if (/^\/(category|page|tag|author|privacy-policy|terms|contact)/i.test(url.pathname)) continue;
                            if (url.pathname === '/' || url.pathname === '') continue;

                            const img = a.querySelector('img');
                            if (img && !foundUrls.has(href)) {
                                foundUrls.add(href);

                                let title = img.alt || img.title || a.title || url.pathname.replace(/\//g, '').replace(/-/g, ' ');
                                let thumbnail_path = img.src || img.dataset?.src;

                                results.push({
                                    id: 'bh-' + Math.random().toString(36).substr(2, 9),
                                    url: href,
                                    title: title.trim(),
                                    thumbnail_path: thumbnail_path,
                                    duration: 0,
                                    views: 0,
                                    sizeBytes: 0,
                                    uploadDate: new Date().toISOString()
                                });
                            }
                        }
                    } catch (e) { }
                }
                return results;
            }
        });

        if (result && result.length > 0) {
            allVideos = result;
            currentlyFilteredVideos = [...allVideos];
            renderGrid(currentlyFilteredVideos);
        } else {
            const container = document.querySelector('.container');
            if (container) container.innerHTML = '<div style="padding:40px;text-align:center;opacity:0.6;"><h3>Nenašli sa žiadne videá</h3><p>Na tejto stránke sa nepodarilo nájsť žiadne Baddiehub videá.</p></div>';
        }
    } catch (e) {
        console.error("Baddiehub scraping error", e);
    } finally {
        document.getElementById('loader').style.display = 'none';
        document.getElementById('video-grid').style.display = 'grid';
    }
}

async function handleTnaflixScrapingLegacy(tab) {
    console.log('Tnaflix scraping:', tab.id, tab.url);
    document.getElementById('loader').style.display = 'flex';
    document.getElementById('video-grid').style.display = 'none';

    try {
        const [{ result }] = await chrome.scripting.executeScript({
            target: { tabId: tab.id },
            func: async () => {
                const results = [];
                const links = document.querySelectorAll('a.video-thumb, a.thumb');
                const foundUrls = new Set();

                for (const a of links) {
                    try {
                        const href = a.href;
                        const url = new URL(href);

                        if (url.hostname.includes('tnaflix.com') && /\/video\d+/.test(url.pathname)) {
                            const img = a.querySelector('img');
                            if (img && !foundUrls.has(href)) {
                                foundUrls.add(href);

                                let title = img.alt || img.title || a.title || url.pathname.split('/').slice(-2)[0] || 'Unknown';
                                let thumbnail_path = img.dataset?.src || img.src;

                                const durationEl = a.querySelector('.video-duration');
                                let durationText = durationEl ? durationEl.textContent.trim() : '00:00';

                                let durParts = durationText.split(':').map(Number);
                                let durSeconds = 0;
                                if (durParts.length === 3) durSeconds = durParts[0] * 3600 + durParts[1] * 60 + durParts[2];
                                else if (durParts.length === 2) durSeconds = durParts[0] * 60 + durParts[1];

                                results.push({
                                    id: 'tna-' + Math.random().toString(36).substr(2, 9),
                                    url: href,
                                    title: title.trim().replace(/-/g, ' '),
                                    thumbnail_path: thumbnail_path,
                                    duration: durSeconds,
                                    views: 0,
                                    sizeBytes: 0,
                                    uploadDate: new Date().toISOString()
                                });
                            }
                        }
                    } catch (e) { }
                }
                return results;
            }
        });

        if (result && result.length > 0) {
            allVideos = result;
            currentlyFilteredVideos = [...allVideos];
            renderGrid(currentlyFilteredVideos);
        } else {
            const container = document.querySelector('.container');
            if (container) container.innerHTML = '<div style="padding:40px;text-align:center;opacity:0.6;"><h3>Nenašli sa žiadne videá</h3><p>Na tejto stránke sa nepodarilo nájsť žiadne TNAFlix videá.</p></div>';
        }
    } catch (e) {
        console.error("TNAFlix scraping error", e);
    } finally {
        document.getElementById('loader').style.display = 'none';
        document.getElementById('video-grid').style.display = 'grid';
    }
}

async function handleFreepornfunScraping(tab) {
    console.log('Freepornfun scraping:', tab.id, tab.url);
    document.getElementById('loader').style.display = 'flex';
    document.getElementById('video-grid').style.display = 'none';

    try {
        const pageLimit = parseInt(document.getElementById('max-pages')?.value || '1', 10);
        const autoSend = document.getElementById('send-to-dashboard')?.checked || false;
        const isTurbo = document.getElementById('turbo-mode')?.checked || false;

        const [{ result }] = await chrome.scripting.executeScript({
            target: { tabId: tab.id },
            func: async (limit) => {
                const results = [];
                let currentPage = 1;
                let hasNextPage = true;
                let currentDoc = document;
                let currentUrl = window.location.href;

                const processGroup = async (targetHref, elements) => {
                    if (!elements || elements.length === 0) return null;

                    let thumb = '';
                    let title = '';

                    for (const el of elements) {
                        if (el.hasAttribute('data-title') && !title) {
                            title = el.getAttribute('data-title');
                        }
                        if (el.hasAttribute('data-images') && !thumb) {
                            try {
                                const images = JSON.parse(el.getAttribute('data-images'));
                                if (Array.isArray(images) && images.length > 0) thumb = images[0];
                            } catch (e) { }
                        }

                        const img = el.querySelector ? el.querySelector('img') : null;
                        if (img && !thumb) {
                            thumb = img.getAttribute('src') || img.getAttribute('data-src') || img.src || '';
                            const srcset = img.getAttribute('srcset');
                            if (srcset && (!thumb || thumb.includes('data:image'))) {
                                thumb = srcset.split(',').pop().trim().split(' ')[0];
                            }
                        }
                        if (!title && el.querySelector) {
                            const titleEl = el.querySelector('h2, h3, div.title, span.title, p.title');
                            if (titleEl && titleEl.innerText.trim().length > 2) {
                                title = titleEl.innerText.trim();
                            }
                        }
                        if (!title && el.getAttribute && el.getAttribute('aria-label')) {
                            title = el.getAttribute('aria-label');
                        }
                    }

                    if (thumb && (thumb.startsWith('/_next/') || thumb.startsWith('/'))) {
                        thumb = window.location.origin + thumb;
                    }

                    if (!title) title = 'FreePornFun Video';

                    let duration = 0;
                    let directUrl = targetHref;
                    if (directUrl && directUrl.startsWith('/')) directUrl = window.location.origin + directUrl;
                    let quality = 'HD';
                    let size = 0;

                    if (targetHref && targetHref.includes('/post/')) {
                        try {
                            const vpResp = await fetch(directUrl);
                            if (vpResp.ok) {
                                const vpHtml = await vpResp.text();

                                const mp4Match = vpHtml.match(/src=["']([^"']+\.mp4[^"']*)["']/i) ||
                                    vpHtml.match(/videoUrl\s*[:=]\s*["']([^"']+)["']/i) ||
                                    vpHtml.match(/["']?url["']?\s*:\s*["']([^"']+\.mp4[^"']*)["']/i) ||
                                    vpHtml.match(/contentUrl["']?\s*:\s*["']([^"']+)["']/i);
                                if (mp4Match) {
                                    directUrl = mp4Match[1].replace(/\\/g, '');
                                    if (directUrl.startsWith('/')) directUrl = window.location.origin + directUrl;
                                }

                                const ptMatch = vpHtml.match(/PT(\d+)M(\d+)S/i) || vpHtml.match(/duration["']?\s*:\s*["']?PT(\d+)M(\d+)S/i);
                                if (ptMatch) {
                                    duration = parseInt(ptMatch[1]) * 60 + parseInt(ptMatch[2]);
                                } else {
                                    const durMatch2 = vpHtml.match(/["']?duration["']?\s*:\s*["']?(\d+:\d+|\d+)["']?/i);
                                    if (durMatch2) {
                                        if (durMatch2[1].includes(':')) {
                                            const p = durMatch2[1].split(':');
                                            if (p.length === 2) duration = parseInt(p[0]) * 60 + parseInt(p[1]);
                                            else if (p.length === 3) duration = parseInt(p[0]) * 3600 + parseInt(p[1]) * 60 + parseInt(p[2]);
                                        } else {
                                            duration = parseInt(durMatch2[1]);
                                        }
                                    } else {
                                        const secMatch = vpHtml.match(/["']?durationSec["']?\s*:\s*(\d+)/i) || vpHtml.match(/["']?duration["']?\s*:\s*(\d+)/i);
                                        if (secMatch) duration = parseInt(secMatch[1]);
                                    }
                                }

                                const qMatch = vpHtml.match(/(1080p|720p|4k|480p)/i);
                                if (qMatch) quality = qMatch[1].toUpperCase();
                            }
                        } catch (e) {
                            console.error("Failed to fetch metadata", e);
                        }
                    }

                    return {
                        url: directUrl,
                        source_url: directUrl,
                        title: title,
                        thumbnail: thumb,
                        duration: duration,
                        quality: quality,
                        size: size,
                        tags: []
                    };
                };

                while (currentPage <= limit && hasNextPage) {
                    let posts = Array.from(currentDoc.querySelectorAll('[data-href*="/post/"]'));
                    if (posts.length === 0) {
                        posts = Array.from(currentDoc.querySelectorAll('a[href*="/post/"]'));
                    }

                    const extractHref = (el) => el.getAttribute('data-href') || el.href || '';
                    const uniqueHrefs = [...new Set(posts.map(el => extractHref(el)))].filter(h => h && !results.some(i => i.source_url.includes(h)));

                    const pagePromises = uniqueHrefs.map(href => {
                        const matchingEls = posts.filter(el => extractHref(el) === href);
                        return processGroup(href, matchingEls);
                    });

                    const pageResults = await Promise.all(pagePromises);
                    pageResults.forEach(r => { if (r && r.url) results.push(r); });

                    const nextBtn = currentDoc.querySelector('a[href*="?page="]:not([disabled])') ||
                        Array.from(currentDoc.querySelectorAll('a')).find(a => a.textContent.trim() === 'Next' || a.textContent.trim() === '>');

                    if (nextBtn && currentPage < limit) {
                        currentPage++;
                        try {
                            const resp = await fetch(nextBtn.href);
                            if (!resp.ok) break;
                            const html = await resp.text();
                            const parser = new DOMParser();
                            currentDoc = parser.parseFromString(html, 'text/html');
                            currentUrl = nextBtn.href;
                        } catch (e) {
                            break;
                        }
                    } else {
                        hasNextPage = false;
                    }
                }
                return results;
            },
            args: [pageLimit]
        });

        allVideos = (result || [])
            .filter(v => v && v.url && v.title)
            .map(v => ({
                id: v.url,
                url: v.url,
                source_url: v.source_url || v.url,
                title: String(v.title).trim(),
                thumbnail: String(v.thumbnail || '').trim(),
                duration: 0,
                quality: String(v.quality || 'HD').trim(),
                size: 0,
                tags: [],
            }));

        currentlyFilteredVideos = [...allVideos];
        const folderEl = document.getElementById('folder-name');
        if (folderEl) {
            folderEl.textContent = `FreePornFun${isTurbo ? ' (Turbo)' : ''}`;
        }
        applyFilters();
        updateStats();

        if (allVideos.length === 0) {
            showError('No media found on freepornfun.com');
        } else if (autoSend) {
            importVideos(allVideos, `FreePornFun ${new Date().toLocaleDateString()}`);
        }
    } catch (err) {
        console.error('handleFreepornfunScraping', err);
        showError('FreePornFun script execution failed: ' + err.message);
    }
}

// ── FAPHOUSE SCRAPER ──────────────────────────────────────────────────────────
async function handleFaphouseScraping(tab) {
    console.log('Faphouse scraping:', tab.id, tab.url);
    document.getElementById('loader').style.display = 'flex';
    document.getElementById('video-grid').style.display = 'none';

    const folderEl = document.getElementById('folder-name');
    if (folderEl?.firstChild) folderEl.firstChild.textContent = 'Faphouse ';

    try {
        const [{ result }] = await chrome.scripting.executeScript({
            target: { tabId: tab.id },
            func: () => {
                // ── helpers ───────────────────────────────────────────────────
                function parseDur(text) {
                    const m = String(text || '').match(/\b(\d{1,2}):(\d{2})(?::(\d{2}))?\b/);
                    if (!m) return 0;
                    const a = +m[1], b = +m[2], c = m[3] != null ? +m[3] : null;
                    return c == null ? a * 60 + b : a * 3600 + b * 60 + c;
                }

                function extractCard(container) {
                    // Anchor: prefer .t-vl (poster link), fall back to any /videos/ link
                    const anchor =
                        container.matches('a[href*="/videos/"]')
                            ? container
                            : (container.querySelector('a.t-vl[href*="/videos/"]') ||
                                container.querySelector('a[href*="/videos/"]'));
                    if (!anchor) return null;

                    const rawHref = anchor.getAttribute('href') || '';
                    if (!rawHref || rawHref === '/videos' || rawHref === '/videos/' ||
                        rawHref.startsWith('/videos/vr')) return null;

                    // Filter category / tag pages (all-lowercase single word)
                    const slug = rawHref.split('?')[0].replace(/\/+$/, '').split('/videos/')[1] || '';
                    const isWatch =
                        anchor.classList.contains('t-vl') ||
                        /-[a-zA-Z0-9]{4,}$/.test(slug) ||
                        (/^[A-Za-z0-9]{5,}$/.test(slug) && /[A-Z]/.test(slug) && /[a-z0-9]/.test(slug));
                    if (!isWatch) return null;

                    let absUrl = '';
                    try { absUrl = new URL(rawHref, location.origin).href.split('#')[0]; }
                    catch { absUrl = rawHref.split('#')[0]; }

                    const id = slug.split('-').pop() || absUrl;

                    const img = container.querySelector('img.t-i, img[src*="flixcdn"], img.thumb-image, img');
                    let thumbnail = img?.getAttribute('src') ||
                        img?.getAttribute('data-src') ||
                        img?.getAttribute('data-lazy-src') ||
                        img?.getAttribute('data-thumb') ||
                        img?.getAttribute('data-original') ||
                        img?.getAttribute('data-poster') ||
                        img?.src || '';

                    if (thumbnail.startsWith('//')) {
                        thumbnail = 'https:' + thumbnail;
                    } else if (thumbnail.startsWith('/')) {
                        try { thumbnail = new URL(thumbnail, location.origin).href; } catch { }
                    }

                    let title = img?.getAttribute('alt') || anchor.getAttribute('title') || '';
                    title = title.replace(/\s+/g, ' ').trim();
                    if (!title || title.length < 3) {
                        const el = container.querySelector('.t-t, .title, h3, h4');
                        if (el) title = el.textContent.trim();
                    }

                    const durEl = container.querySelector('.t-vi, .duration, [class*="duration"]');
                    const durText = durEl?.textContent || '';
                    const duration = parseDur(durText);
                    const quality = /4K|2160/i.test(durText) ? '2160p' : /HD/i.test(durText) ? '1080p' : '';

                    return {
                        id: 'fh-' + id,
                        url: absUrl,
                        source_url: absUrl,
                        title: title || ('Faphouse Video ' + id),
                        thumbnail: thumbnail,
                        thumbnail_path: thumbnail,
                        thumbnail_original: thumbnail,
                        duration,
                        quality,
                        views: 0,
                        sizeBytes: 0,
                        uploadDate: ''
                    };
                }

                // ── DOM scan (same priority order as faphouse_grid_importer.js) ─
                const selectors = [
                    '[data-el="Thumb"][data-id]',
                    '[data-id][data-el-video]',
                    '.thumb:has(a[href*="/videos/"])',
                    '.t-m',
                    '[data-el="VideoCard"]',
                    '.video-item',
                ];

                let nodes = [];
                for (const sel of selectors) {
                    try {
                        const found = Array.from(document.querySelectorAll(sel))
                            .filter(n => n.querySelector('img'));
                        if (found.length) { nodes = found; break; }
                    } catch { }
                }
                if (!nodes.length) {
                    try {
                        nodes = Array.from(document.querySelectorAll('div:has(> a[href*="/videos/"])'))
                            .filter(n => n.querySelector('img'));
                    } catch { }
                }
                if (!nodes.length) {
                    nodes = Array.from(document.querySelectorAll('a[href*="/videos/"]:has(img)'));
                }

                const seen = new Set();
                const results = [];
                for (const node of nodes) {
                    const item = extractCard(node);
                    if (!item || seen.has(item.id)) continue;
                    seen.add(item.id);
                    results.push(item);
                }

                // ── single watch page fallback ────────────────────────────────
                if (!results.length && /\/videos\/[a-zA-Z0-9_-]+/.test(location.pathname)) {
                    const id = location.pathname.replace(/\/+$/, '').split('/').pop() || location.href;
                    results.push({
                        id: 'fh-' + id,
                        url: location.href.split('#')[0],
                        title: document.querySelector('h1')?.textContent?.trim() ||
                            document.querySelector('meta[property="og:title"]')?.content ||
                            document.title,
                        thumbnail_path: document.querySelector('meta[property="og:image"]')?.content || '',
                        duration: Math.round(document.querySelector('video')?.duration || 0) || 0,
                        quality: '',
                        views: 0,
                        sizeBytes: 0,
                        uploadDate: ''
                    });
                }

                return results;
            }
        });

        if (result && result.length > 0) {
            // FapHouse streams are signed and short-lived. Restore only a
            // still-valid cached stream before rendering; otherwise a card is
            // resolved again through the logged-in source tab when it plays.
            const cacheHits = await hydrateFaphouseCardsFromCache(result);
            allVideos = result;
            currentlyFilteredVideos = [...allVideos];
            renderGrid(currentlyFilteredVideos);
            saveToCache(tab.url, allVideos);
            scheduleFaphouseCardCacheSave(allVideos);
            if (cacheHits) showToast(`↗ Cache: ${cacheHits} FapHouse kariet doplnených bez ďalšieho načítania.`, 3500);
        } else {
            const container = document.querySelector('.container');
            if (container) {
                container.innerHTML = '<div style="padding:40px;text-align:center;opacity:0.6;">' +
                    '<h3>Nenašli sa žiadne videá</h3>' +
                    '<p>Uisti sa, že si na stránke Faphouse s videami (nie na hlavnej stránke alebo kategórii).</p>' +
                    '</div>';
            }
        }
    } catch (err) {
        console.error('handleFaphouseScraping error', err);
        showError('Faphouse: ' + err.message);
    } finally {
        document.getElementById('loader').style.display = 'none';
        document.getElementById('video-grid').style.display = 'grid';
        updateStats();
    }
}
